insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('e1000000-0000-0000-0000-000000000001', 'ukmla', '9d05fb0b-2696-44ec-8350-15a6911bee57',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('e1000000-0000-0000-0000-000000000001', 'A', 'Reassure the mother that bruising is common in infants and discharge with routine health visitor follow-up', false, 'Ruled out because a non-mobile infant cannot generate accidental bruising through his own activity; multiple bruises of different ages in this context are a red flag for abuse that must not be dismissed as normal.', 1),
('e1000000-0000-0000-0000-000000000001', 'B', 'Refer urgently to the paediatric safeguarding team and admit for a full assessment', true, 'Correct. Bruises of varying ages, in a non-mobile infant, over non-bony/soft-tissue sites (trunk, buttocks) with no adequate explanation are highly suggestive of physical abuse. This pattern in a pre-mobile baby cannot be self-inflicted, so an urgent safeguarding referral and admission for full assessment (including skeletal survey and senior review) is mandatory.', 2),
('e1000000-0000-0000-0000-000000000001', 'C', 'Document the findings and only refer to safeguarding if further bruises are noted at the next visit', false, $x$Ruled out because delaying action risks further, potentially fatal, harm to the child; concerning bruising in a pre-mobile infant requires immediate action, not a 'wait and see' approach.$x$, 3),
('e1000000-0000-0000-0000-000000000001', 'D', 'Arrange outpatient clotting studies and review the results before deciding on further action', false, 'Ruled out because although a bleeding disorder should be considered and can be tested for, the priority in an unexplained bruising pattern like this in a non-mobile infant is urgent safeguarding referral; investigations for bleeding disorders are arranged alongside, not instead of, this.', 4),
('e1000000-0000-0000-0000-000000000001', 'E', 'Ask the mother to bring the infant back in one week if any new bruises appear', false, 'Ruled out because this places the burden of monitoring on a potentially unsafe home environment and delays protective action for a child who may be at ongoing risk.', 5),
('e1000000-0000-0000-0000-000000000002', 'A', 'Reassure the parents that this is entirely normal variation and review again at 3 years', false, 'Ruled out because not walking by 18 months and stalled language progress both fall outside the normal range of milestone attainment and should prompt assessment now, not a deferred review after a further 18 months.', 1),
('e1000000-0000-0000-0000-000000000002', 'B', 'Arrange an urgent CT brain as the first investigation', false, 'Ruled out because neuroimaging is not the first-line step for isolated delayed walking and language plateau; a structured developmental assessment (including hearing test and holistic review) comes first and guides any further investigation.', 2),
('e1000000-0000-0000-0000-000000000002', 'C', 'Refer for a formal developmental assessment as gross motor and language milestones are outside the expected range', true, 'Correct. Most children walk independently by 15 months (definitely by 18 months) and gain new words steadily through the second year; failure to walk by 18 months and a language plateau since 12 months both warrant formal developmental assessment to identify an underlying cause and initiate early support.', 3),
('e1000000-0000-0000-0000-000000000002', 'D', 'Advise that this is likely autism spectrum disorder and refer directly for an autism diagnostic assessment only', false, 'Ruled out because the vignette describes joint attention (pointing) and reciprocal social play (peekaboo), which are not typical of autism; a broad developmental assessment is needed rather than assuming a single diagnosis.', 4),
('e1000000-0000-0000-0000-000000000002', 'E', 'No action needed as he can pull to stand and cruise, which is sufficient gross motor progress', false, 'Ruled out because cruising alone is not equivalent to independent walking, which is expected by 15-18 months; combined with the language plateau this needs assessment, not dismissal.', 5),
('e1000000-0000-0000-0000-000000000003', 'A', 'Growth hormone deficiency', false, 'Ruled out because growth hormone deficiency typically causes a falling growth velocity that crosses centiles downward over time, not a steady trajectory parallel to a centile line; the reassuring family history and proportionate delayed bone age favour a constitutional pattern.', 1),
('e1000000-0000-0000-0000-000000000003', 'B', 'Familial short stature', false, 'Ruled out because familial short stature is associated with a bone age that matches chronological age (not delayed) and predicted adult height in keeping with parental heights, whereas this boy has a bone age delayed by two years and a family history of delayed (not short) growth.', 2),
('e1000000-0000-0000-0000-000000000003', 'C', 'Turner syndrome', false, 'Ruled out because Turner syndrome occurs only in girls (45,X karyotype) and this patient is male; it is not a relevant differential here.', 3),
('e1000000-0000-0000-0000-000000000003', 'D', 'Constitutional delay of growth and puberty', true, 'Correct. A steady growth velocity tracking along (not falling away from) a low-normal centile, delayed bone age matching the degree of height delay, pre-pubertal staging appropriate for the delayed bone age, and a positive family history of late puberty are the classic features of constitutional delay of growth and puberty, a normal variant that requires reassurance and monitoring rather than treatment.', 4),
('e1000000-0000-0000-0000-000000000003', 'E', 'Precocious puberty', false, 'Ruled out because precocious puberty refers to early onset of pubertal changes (before 9 years in boys), whereas this boy is pre-pubertal at 13 years, the opposite pattern to what is described.', 5),
('e1000000-0000-0000-0000-000000000004', 'A', 'Admit the child, arrange a skeletal survey, and make an urgent safeguarding referral', true, 'Correct. A metaphyseal (bucket-handle/corner) fracture in a non-mobile infant with no history of trauma is one of the fracture patterns with the highest specificity for non-accidental injury. Safe practice is admission, a skeletal survey to look for other occult injuries, senior paediatric and safeguarding team involvement, and formal child protection referral.', 1),
('e1000000-0000-0000-0000-000000000004', 'B', 'Apply a splint and discharge with outpatient orthopaedic follow-up', false, 'Ruled out because discharging a non-mobile infant with an unexplained, highly suspicious fracture pattern without safeguarding assessment risks the child returning to an unsafe environment; admission and safeguarding referral are required before discharge is considered.', 2),
('e1000000-0000-0000-0000-000000000004', 'C', 'Reassure the family that metaphyseal fractures are a normal variant of infant bone growth', false, 'Ruled out because metaphyseal/corner fractures are not a normal developmental variant; they are strongly associated with a shearing/twisting mechanism typical of abusive injury in a non-mobile infant.', 3),
('e1000000-0000-0000-0000-000000000004', 'D', 'Request genetic testing for osteogenesis imperfecta before taking any safeguarding action', false, 'Ruled out because although osteogenesis imperfecta is a differential for unexplained fractures and can be considered as part of the wider assessment, it must not delay urgent safeguarding action; the two are pursued in parallel, not sequentially with safeguarding deferred.', 4),
('e1000000-0000-0000-0000-000000000004', 'E', 'Discharge with simple analgesia as the injury does not appear severe on examination', false, 'Ruled out because the severity of the fracture on examination is irrelevant to the safeguarding concern raised by an unexplained metaphyseal fracture in a pre-mobile infant, which mandates protective action regardless of how minor the injury looks clinically.', 5),
('e1000000-0000-0000-0000-000000000005', 'A', 'Normal motor milestones excluding any neurodevelopmental concern', false, 'Ruled out because autism spectrum disorder is a disorder of social communication and behaviour, not motor development; normal motor milestones do not exclude it, and isolated motor delay is not a typical autism marker.', 1),
('e1000000-0000-0000-0000-000000000005', 'B', 'A normal newborn hearing screen excluding the possibility of a communication disorder', false, 'Ruled out because a normal newborn hearing screen only confirms peripheral hearing at birth; it does not exclude autism spectrum disorder or later-onset hearing loss, and absent language in this context is a social-communication red flag, not simply a hearing issue.', 2),
('e1000000-0000-0000-0000-000000000005', 'C', 'Lining up toys being a sign of advanced cognitive ability rather than a concern', false, 'Ruled out because rigid, repetitive play (such as insistently lining up objects) combined with distress on disruption of routines is a recognised behavioural red flag for autism, not a marker of advanced ability.', 3),
('e1000000-0000-0000-0000-000000000005', 'D', 'Walking at 13 months being outside the normal range and the primary concern', false, 'Ruled out because walking at 13 months is within the normal range (up to 18 months) and is not a concern; the genuinely concerning features are the social communication and language red flags.', 4),
('e1000000-0000-0000-0000-000000000005', 'E', 'Lack of joint attention (no pointing), poor eye contact, absent language, and repetitive/rigid play', true, 'Correct. Reduced joint attention (not pointing to share interest), avoidance of eye contact, language delay, and rigid, repetitive play with distress at disruption to routine are core early red flags for autism spectrum disorder and should prompt referral for a multidisciplinary developmental/autism assessment.', 5),
('e1000000-0000-0000-0000-000000000006', 'A', 'Accidental fall from a low height as described by the parents', false, 'Ruled out because low-height accidental falls very rarely cause subdural haematoma with retinal haemorrhages and encephalopathy in infants; this combination of findings is disproportionate to trivial trauma and no such trauma has even been described.', 1),
('e1000000-0000-0000-0000-000000000006', 'B', 'Abusive head trauma (non-accidental injury)', true, $x$Correct. The triad of subdural haematoma, retinal haemorrhages, and encephalopathy (reduced consciousness, focal neurology) in an infant with no history of significant accidental trauma is highly specific for abusive head trauma ('shaken baby syndrome'). Absence of external bruising does not exclude this, as the causative shaking/impact forces can occur without leaving skin marks. This requires urgent safeguarding referral alongside acute stabilisation.$x$, 2),
('e1000000-0000-0000-0000-000000000006', 'C', 'Idiopathic intracranial hypertension', false, 'Ruled out because this is a condition of raised intracranial pressure typically seen in older, often obese individuals with papilloedema and headache, not an acute subdural haematoma with retinal haemorrhages in a 6-week-old infant.', 3),
('e1000000-0000-0000-0000-000000000006', 'D', 'Vitamin K deficiency bleeding', false, 'Ruled out because although vitamin K deficiency bleeding can cause intracranial haemorrhage in young infants, it does not typically produce retinal haemorrhages, and this diagnosis should specifically be considered and excluded (checking vitamin K prophylaxis history and clotting) rather than assumed as the primary explanation given the classic triad present here.', 4),
('e1000000-0000-0000-0000-000000000006', 'E', 'Meningitis with associated coagulopathy', false, 'Ruled out because there are no features of sepsis or meningeal infection (no fever, no rash, no CSF findings mentioned) to support this, and it would not typically explain focal retinal haemorrhages combined with a subdural haematoma.', 5),
('e1000000-0000-0000-0000-000000000007', 'A', 'Reassure the parents that some infants naturally settle onto a lower centile after birth', false, 'Ruled out because while an initial settling onto a lower centile in the first weeks of life can be normal, crossing two major centile lines after early infancy is a definition of faltering growth that requires assessment, not simple reassurance.', 1),
('e1000000-0000-0000-0000-000000000007', 'B', $x$Advise stopping formula feeds and starting cow's milk immediately$x$, false, $x$Ruled out because cow's milk is not nutritionally appropriate or recommended as a primary drink before 12 months of age, and switching feeds without an assessment does not address the underlying cause of the faltering growth.$x$, 2),
('e1000000-0000-0000-0000-000000000007', 'C', 'Refer directly for gastrostomy feeding without further assessment', false, 'Ruled out because gastrostomy feeding is a highly invasive intervention reserved for cases where oral/enteral feeding has failed despite thorough assessment and less invasive measures; it is not an appropriate first step here.', 3),
('e1000000-0000-0000-0000-000000000007', 'D', 'Take a detailed feeding history, examine thoroughly, and arrange baseline investigations to look for an organic cause', true, 'Correct. A weight that has crossed two or more centile lines downward meets the definition of faltering growth and requires systematic assessment: a detailed feeding/dietary history, thorough examination, and baseline investigations (e.g. urine, coeliac screen, full blood count) to look for an organic cause, alongside consideration of feeding technique and psychosocial factors, before assuming a benign cause.', 4),
('e1000000-0000-0000-0000-000000000007', 'E', 'No action needed as his development is otherwise normal', false, 'Ruled out because normal developmental milestones do not exclude an underlying cause for faltering growth; growth and development are assessed separately, and significant centile crossing always warrants further assessment.', 5),
('e1000000-0000-0000-0000-000000000008', 'A', 'Physiological jaundice of the newborn', false, 'Ruled out because physiological jaundice characteristically appears after 24 hours of age (typically day 2-5) and resolves by around day 10; jaundice within the first 24 hours of life is never physiological and always requires urgent investigation.', 1),
('e1000000-0000-0000-0000-000000000008', 'B', 'Breast milk jaundice', false, 'Ruled out because breast milk jaundice is a prolonged, unconjugated jaundice typically persisting beyond 2 weeks in an otherwise well, thriving infant, not an early-onset jaundice within 24 hours associated with a positive Coombs test.', 2),
('e1000000-0000-0000-0000-000000000008', 'C', 'ABO incompatibility causing haemolysis', true, 'Correct. Jaundice appearing within the first 24 hours of life is always pathological and most commonly due to haemolysis. A mother who is blood group O with a baby who is group A or B is at risk of ABO incompatibility, in which maternal anti-A/anti-B antibodies cross the placenta and haemolyse fetal red cells; a positive direct antiglobulin test confirms an immune-mediated haemolytic process.', 3),
('e1000000-0000-0000-0000-000000000008', 'D', 'Biliary atresia', false, 'Ruled out because biliary atresia causes a conjugated hyperbilirubinaemia presenting with prolonged jaundice (beyond 14 days) and pale stools/dark urine, not haemolytic jaundice within the first day of life with a positive direct antiglobulin test.', 4),
('e1000000-0000-0000-0000-000000000008', 'E', 'Physiological polycythaemia leading to increased bilirubin load', false, 'Ruled out because there is no mention of polycythaemia here, and the positive direct antiglobulin test specifically points to an immune haemolytic process (ABO incompatibility) rather than an incidental rise in red cell mass.', 5),
('e1000000-0000-0000-0000-000000000009', 'A', 'An isolated raised unconjugated bilirubin with all other findings normal', false, 'Ruled out because an isolated unconjugated hyperbilirubinaemia in an otherwise well, thriving, exclusively breastfed infant is most consistent with benign breast milk jaundice, not a cause requiring urgent surgical referral; pale stools and dark urine described here specifically point towards a conjugated problem instead.', 1),
('e1000000-0000-0000-0000-000000000009', 'B', 'A mildly elevated haemoglobin consistent with normal neonatal polycythaemia', false, 'Ruled out because a normal haemoglobin range is not relevant to identifying a serious cause of prolonged jaundice and does not indicate biliary obstruction.', 2),
('e1000000-0000-0000-0000-000000000009', 'C', 'Normal liver transaminases', false, 'Ruled out because normal transaminases would be reassuring rather than concerning, and would not explain pale stools and dark urine; it is the conjugated bilirubin fraction that is the key discriminating investigation here.', 3),
('e1000000-0000-0000-0000-000000000009', 'D', 'A negative direct antiglobulin test', false, 'Ruled out because a negative Coombs test simply excludes an immune haemolytic cause; it does not address or explain the pale stools and dark urine, which point towards a biliary/hepatic cause requiring assessment of conjugated bilirubin.', 4),
('e1000000-0000-0000-0000-000000000009', 'E', 'A raised conjugated (direct) bilirubin fraction', true, 'Correct. Prolonged jaundice (beyond 14 days in a term infant) with pale stools and dark urine raises concern for biliary atresia or another cause of conjugated hyperbilirubinaemia. A raised conjugated bilirubin fraction in this context is a red flag requiring urgent referral to a specialist paediatric liver centre, as early diagnosis and surgery (Kasai procedure) before 6 weeks of age significantly improves outcomes.', 5),
('e1000000-0000-0000-0000-000000000010', 'A', 'Take blood cultures and start intravenous benzylpenicillin and gentamicin without delay', true, 'Correct. This baby has significant risk factors for early-onset neonatal sepsis (maternal GBS colonisation without adequate intrapartum antibiotic prophylaxis) and is now showing clinical signs of sepsis (lethargy, grunting, tachypnoea, temperature instability). Blood cultures should be taken but empirical intravenous antibiotics (benzylpenicillin and gentamicin per local/national early-onset sepsis guidance) must be started immediately without waiting for culture results, given the rapid and life-threatening course of neonatal sepsis.', 1),
('e1000000-0000-0000-0000-000000000010', 'B', 'Observe on the postnatal ward with hourly observations and treat only if he deteriorates further', false, 'Ruled out because a baby with significant sepsis risk factors and current clinical signs of illness needs empirical antibiotics started immediately; delaying treatment pending further deterioration risks rapid progression to severe sepsis and death, which can occur within hours in neonates.', 2),
('e1000000-0000-0000-0000-000000000010', 'C', 'Give oral amoxicillin and review in 24 hours', false, 'Ruled out because oral antibiotics do not achieve adequate levels or speed of action for suspected neonatal sepsis, which requires intravenous therapy; a 24-hour review is far too delayed for a potentially septic neonate.', 3),
('e1000000-0000-0000-0000-000000000010', 'D', 'Perform a lumbar puncture as the first and only investigation before starting any treatment', false, 'Ruled out because although a lumbar puncture may be indicated as part of a full septic screen, it should not delay the priority of starting empirical intravenous antibiotics in a clinically unwell neonate with sepsis risk factors.', 4),
('e1000000-0000-0000-0000-000000000010', 'E', 'Reassure the parents that grunting and tachypnoea are normal transitional findings after birth', false, 'Ruled out because although mild transient tachypnoea can occur after birth, the combination of maternal GBS risk factors without adequate prophylaxis, lethargy, and temperature instability at 6 hours of age is a sepsis red flag that must not be dismissed as normal transition.', 5),
('e1000000-0000-0000-0000-000000000011', 'A', 'Transient tachypnoea of the newborn', false, 'Ruled out because transient tachypnoea of the newborn typically occurs in term or near-term infants (often after caesarean section without labour) due to delayed clearance of lung fluid, causing streaky perihilar changes on X-ray that resolve within 24-48 hours, not the ground-glass/air bronchogram appearance of surfactant deficiency in a very preterm infant.', 1),
('e1000000-0000-0000-0000-000000000011', 'B', 'Meconium aspiration syndrome', false, 'Ruled out because meconium aspiration syndrome occurs in the context of meconium-stained liquor, typically in term or post-term infants, causing patchy consolidation and hyperinflation, not the diffuse ground-glass pattern described in this very preterm infant.', 2),
('e1000000-0000-0000-0000-000000000011', 'C', 'Congenital diaphragmatic hernia', false, 'Ruled out because this would typically present with scaphoid abdomen and bowel loops visible within the thorax on chest X-ray, often with mediastinal shift, rather than a diffuse ground-glass pattern with air bronchograms.', 3),
('e1000000-0000-0000-0000-000000000011', 'D', 'Persistent pulmonary hypertension of the newborn', false, 'Ruled out because this typically occurs in term or post-term infants with a history of perinatal stress (e.g. meconium aspiration, sepsis) and presents with severe hypoxaemia often out of proportion to chest X-ray findings, rather than the classic surfactant-deficiency pattern seen here.', 4),
('e1000000-0000-0000-0000-000000000011', 'E', 'Respiratory distress syndrome due to surfactant deficiency', true, 'Correct. This clinical picture (prematurity, especially without antenatal steroids, early-onset respiratory distress with grunting, recession, and tachypnoea, plus a ground-glass appearance with air bronchograms on chest X-ray) is classic for respiratory distress syndrome caused by surfactant deficiency in the immature lung. Management includes respiratory support (CPAP or ventilation) and exogenous surfactant administration.', 5),
('e1000000-0000-0000-0000-000000000012', 'A', 'Give a feed (breast or formula) and recheck blood glucose shortly after; if it remains low or he is symptomatic, treat with intravenous dextrose', true, 'Correct. Infants of diabetic mothers are at high risk of neonatal hypoglycaemia due to fetal hyperinsulinaemia from in-utero exposure to maternal hyperglycaemia. Symptomatic hypoglycaemia (jitteriness, floppiness, poor feeding) with a significantly low glucose requires prompt correction; an initial feed with close monitoring is reasonable, but persistent or severe symptomatic hypoglycaemia (as here, with clear symptoms and a very low reading) should be escalated promptly to intravenous dextrose if not rapidly corrected, with neonatal unit involvement.', 1),
('e1000000-0000-0000-0000-000000000012', 'B', 'Reassure the parents that jitteriness is a normal newborn finding and no glucose monitoring is needed', false, 'Ruled out because an infant of a diabetic mother with jitteriness, floppiness, and poor feeding must have blood glucose checked and treated appropriately; this is a recognised, potentially dangerous complication of maternal diabetes, not a normal variant to be dismissed.', 2),
('e1000000-0000-0000-0000-000000000012', 'C', 'Delay any treatment until the baby is 4 hours old, as glucose naturally rises after birth', false, 'Ruled out because a markedly low blood glucose with clinical symptoms in a high-risk infant requires prompt action, not a scheduled delay; untreated symptomatic neonatal hypoglycaemia carries a risk of seizures and neurological injury.', 3),
('e1000000-0000-0000-0000-000000000012', 'D', 'Start the baby on oral hypoglycaemic medication', false, 'Ruled out because oral hypoglycaemic agents (used to lower glucose in diabetes) are entirely inappropriate for a neonate with hypoglycaemia, where the goal is to raise, not lower, blood glucose.', 4),
('e1000000-0000-0000-0000-000000000012', 'E', 'Transfer immediately to a tertiary surgical centre for pancreatic surgery', false, 'Ruled out because transient neonatal hypoglycaemia secondary to maternal diabetes is managed medically with feeding and, if needed, intravenous dextrose; pancreatic surgery is not an appropriate or relevant intervention for this common, usually self-limiting condition.', 5),
('e1000000-0000-0000-0000-000000000013', 'A', 'Continue current feeds but reduce the volume slightly and reassess in 24 hours', false, 'Ruled out because continuing any enteral feeding in suspected necrotising enterocolitis risks worsening bowel ischaemia/perforation; feeds must be stopped completely, not merely reduced, while the bowel is rested and the infant is stabilised.', 1),
('e1000000-0000-0000-0000-000000000013', 'B', 'Stop enteral feeds, insert a nasogastric tube for decompression, start broad-spectrum intravenous antibiotics, and involve the neonatal surgical team', true, 'Correct. This presentation (abdominal distension, bilious vomiting, bloody stools, systemic instability, and pneumatosis intestinalis on X-ray in a preterm infant) is classic for necrotising enterocolitis. Immediate management is to stop enteral feeds, decompress the bowel with a nasogastric tube, start broad-spectrum intravenous antibiotics, provide supportive care (fluids, respiratory support as needed), and involve the neonatal surgical team early in case of perforation or failure to improve with medical management.', 2),
('e1000000-0000-0000-0000-000000000013', 'C', 'Perform an urgent barium enema to assess bowel transit', false, 'Ruled out because contrast enema is not appropriate or indicated in suspected necrotising enterocolitis and risks precipitating perforation; plain abdominal X-ray is used for monitoring, and management is medical/surgical rather than requiring contrast studies.', 3),
('e1000000-0000-0000-0000-000000000013', 'D', 'Give a single dose of oral probiotics and continue feeding as tolerated', false, 'Ruled out because once necrotising enterocolitis is suspected, feeds must be stopped entirely rather than continued with an added probiotic, which has no role in acute treatment of established disease.', 4),
('e1000000-0000-0000-0000-000000000013', 'E', 'Discharge home with outpatient paediatric surgical follow-up once stable on the ward', false, 'Ruled out because necrotising enterocolitis is a life-threatening emergency requiring inpatient intensive management (feeds stopped, antibiotics, close monitoring, surgical involvement), not outpatient follow-up.', 5),
('e1000000-0000-0000-0000-000000000014', 'A', 'Active rewarming and swaddling to maintain a higher core temperature', false, 'Ruled out because active warming would be harmful in this context; the evidence-based intervention for moderate-to-severe hypoxic-ischaemic encephalopathy is controlled cooling, not maintaining or raising temperature.', 1),
('e1000000-0000-0000-0000-000000000014', 'B', 'Discharge home once resuscitation is complete with community neonatal follow-up', false, 'Ruled out because an infant with evolving hypoxic-ischaemic encephalopathy after significant perinatal asphyxia requires close inpatient neonatal intensive care monitoring (including for seizures and multi-organ dysfunction), not discharge home.', 2),
('e1000000-0000-0000-0000-000000000014', 'C', 'Start maintenance antiepileptic medication for six months regardless of ongoing seizure activity', false, 'Ruled out because while acute seizures secondary to hypoxic-ischaemic encephalopathy are treated as they occur, committing to six months of maintenance antiepileptic therapy is not the standard immediate management step and is not determined at this early stage.', 3),
('e1000000-0000-0000-0000-000000000014', 'D', 'Therapeutic cooling (targeted temperature management) initiated as soon as possible, ideally within 6 hours of birth', true, 'Correct. This presentation (perinatal asphyxia with severe acidosis, low Apgar scores requiring prolonged resuscitation, and evolving encephalopathy with abnormal tone, reduced consciousness, and seizures) indicates moderate-to-severe hypoxic-ischaemic encephalopathy. Therapeutic hypothermia, started as soon as possible and ideally within 6 hours of birth in an appropriately monitored neonatal intensive care setting, reduces the risk of death and long-term neurodevelopmental disability.', 4),
('e1000000-0000-0000-0000-000000000014', 'E', 'Perform an urgent lumbar puncture as the first priority to exclude meningitis', false, 'Ruled out because the clinical picture here (perinatal asphyxia, acidosis, resuscitation, evolving encephalopathy) is characteristic of hypoxic-ischaemic injury rather than infection; while sepsis is often considered in an unwell neonate, the immediate priority intervention is initiating therapeutic cooling, not lumbar puncture first.', 5),
('e1000000-0000-0000-0000-000000000015', 'A', 'Arrange urgent surgical closure within the next few days', false, 'Ruled out because surgical closure is reserved for larger defects causing heart failure, failure to thrive, or pulmonary hypertension; a small, asymptomatic VSD in a thriving infant does not need urgent or even routine surgical closure at this stage.', 1),
('e1000000-0000-0000-0000-000000000015', 'B', 'Start diuretic therapy immediately to prevent heart failure', false, 'Ruled out because there is no evidence of heart failure (she is thriving and asymptomatic) in this small VSD, so diuretics are not indicated; they are reserved for symptomatic defects causing volume overload.', 2),
('e1000000-0000-0000-0000-000000000015', 'C', 'Reassure the parents and arrange routine cardiology follow-up, as small VSDs frequently close spontaneously', true, 'Correct. Small ventricular septal defects in an asymptomatic, thriving infant with no evidence of pulmonary hypertension or heart failure are managed conservatively, as a substantial proportion close spontaneously over the first years of life. Routine surveillance with paediatric cardiology follow-up (clinical review and serial echocardiograms) is appropriate rather than immediate intervention.', 3),
('e1000000-0000-0000-0000-000000000015', 'D', 'Advise that this murmur is innocent and no follow-up is required', false, 'Ruled out because a pansystolic murmur at the left lower sternal border confirmed on echocardiogram to represent a structural VSD is not an innocent murmur, and ongoing cardiology follow-up is still required even though intervention is not needed now.', 4),
('e1000000-0000-0000-0000-000000000015', 'E', 'Refer for immediate cardiac catheterisation to close the defect percutaneously', false, 'Ruled out because catheter-based closure, like surgery, is reserved for defects causing significant symptoms or haemodynamic compromise; it is not indicated for a small, asymptomatic, likely self-resolving VSD.', 5),
('e1000000-0000-0000-0000-000000000016', 'A', 'Place the infant in the knee-to-chest position, give high-flow oxygen, and keep him calm; escalate to morphine and a beta-blocker if it does not settle', true, $x$Correct. This is a hypercyanotic ('tet') spell, precipitated by crying/agitation, in which increased right ventricular outflow tract obstruction and right-to-left shunting cause worsening cyanosis and a paradoxically softer murmur. First-line management is calming the infant, the knee-to-chest position (increases systemic vascular resistance and reduces right-to-left shunt) and high-flow oxygen; if this fails to settle the spell, morphine (reduces hyperpnoea) and a beta-blocker (relieves infundibular spasm) are used, escalating further if needed.$x$, 1),
('e1000000-0000-0000-0000-000000000016', 'B', 'Perform immediate cardioversion', false, 'Ruled out because a tet spell is caused by dynamic right ventricular outflow tract obstruction and shunting, not an arrhythmia; cardioversion is not indicated and would not address the underlying mechanism.', 2),
('e1000000-0000-0000-0000-000000000016', 'C', 'Give a fluid bolus and place the infant flat on his back', false, 'Ruled out because lying flat does not increase systemic vascular resistance in the way the knee-to-chest position does, and this position is the specific first-line manoeuvre for a tet spell; fluid may have an adjunct role but positioning and oxygen come first.', 3),
('e1000000-0000-0000-0000-000000000016', 'D', 'Reassure the parents that this is expected and no intervention is required', false, 'Ruled out because a hypercyanotic spell is a potentially life-threatening event that can progress to severe hypoxaemia, seizures, or death if untreated, and requires active management, not simple reassurance.', 4),
('e1000000-0000-0000-0000-000000000016', 'E', 'Give an immediate intravenous diuretic', false, 'Ruled out because a tet spell reflects worsening right-to-left shunting due to outflow obstruction, not fluid overload, so diuretics do not address the mechanism and are not first-line treatment.', 5),
('e1000000-0000-0000-0000-000000000017', 'A', 'Patent ductus arteriosus', false, $x$Ruled out because a patent ductus arteriosus classically causes a continuous 'machinery' murmur and does not typically cause radiofemoral delay or a blood pressure differential between arms and legs.$x$, 1),
('e1000000-0000-0000-0000-000000000017', 'B', 'Coarctation of the aorta', true, 'Correct. Radiofemoral delay (weak, delayed femoral pulses relative to brachial pulses), upper-limb hypertension with lower blood pressure in the legs, and a murmur best heard over the back are the classic findings of coarctation of the aorta, a narrowing of the aorta usually just distal to the left subclavian artery origin. This requires prompt cardiology referral for confirmation (echocardiogram) and consideration of intervention (surgical repair or balloon angioplasty/stenting).', 2),
('e1000000-0000-0000-0000-000000000017', 'C', 'Ventricular septal defect', false, 'Ruled out because a VSD causes a pansystolic murmur at the left sternal border and does not cause radiofemoral delay or differential limb blood pressures.', 3),
('e1000000-0000-0000-0000-000000000017', 'D', 'Essential (primary) hypertension', false, 'Ruled out because essential hypertension is rare in young children and does not explain radiofemoral delay or a limb blood pressure differential; a secondary structural cause such as coarctation should be actively sought in a hypertensive child with these findings.', 4),
('e1000000-0000-0000-0000-000000000017', 'E', 'Renal artery stenosis', false, 'Ruled out because although renal artery stenosis is an important cause of secondary hypertension in children, it does not produce radiofemoral delay or a back murmur, which are specific findings for aortic coarctation.', 5),
('e1000000-0000-0000-0000-000000000018', 'A', 'Start a prostaglandin E1 infusion to keep the duct open', false, 'Ruled out because prostaglandin E1 is used to keep the ductus arteriosus open in duct-dependent congenital heart lesions; here the goal is the opposite -- promoting closure of a haemodynamically significant PDA causing symptoms.', 1),
('e1000000-0000-0000-0000-000000000018', 'B', 'Immediate surgical ligation as the only effective treatment', false, 'Ruled out because surgical ligation is generally reserved for infants who fail or are unsuitable for pharmacological closure, not as the automatic first-line approach; a trial of a COX inhibitor is tried first in most cases.', 2),
('e1000000-0000-0000-0000-000000000018', 'C', 'Pharmacological closure with a cyclo-oxygenase inhibitor such as ibuprofen or indomethacin', true, 'Correct. A haemodynamically significant patent ductus arteriosus in a preterm infant (continuous murmur, bounding pulses, widened pulse pressure, increasing respiratory support needs, and echocardiographic evidence of significant shunting) is typically managed first-line with a cyclo-oxygenase inhibitor (ibuprofen or indomethacin), which promotes ductal closure by inhibiting prostaglandin synthesis, reserving surgical ligation for cases where pharmacological closure fails or is contraindicated.', 3),
('e1000000-0000-0000-0000-000000000018', 'D', 'Reassure the parents that this will resolve without any intervention and no treatment is needed', false, 'Ruled out because a haemodynamically significant PDA causing increasing respiratory support requirements and cardiac dilatation requires active treatment, not observation alone, given the risk of ongoing complications such as worsening respiratory status and necrotising enterocolitis.', 4),
('e1000000-0000-0000-0000-000000000018', 'E', 'Start broad-spectrum intravenous antibiotics', false, 'Ruled out because there is no indication of infection here; the clinical picture is one of a haemodynamically significant structural shunt (PDA), not sepsis, so antibiotics are not the appropriate treatment.', 5),
('e1000000-0000-0000-0000-000000000019', 'A', 'Give high-flow 100% oxygen and expect saturations to normalise', false, 'Ruled out because failure of saturations to improve substantially with 100% oxygen (an abnormal hyperoxia test) is itself a key clue pointing away from a primary respiratory cause towards cyanotic congenital heart disease, where oxygen has limited benefit and may even be harmful in some duct-dependent lesions by promoting ductal closure.', 1),
('e1000000-0000-0000-0000-000000000019', 'B', 'Reassure the parents that this is a normal transitional finding and discharge home', false, 'Ruled out because acute collapse with poor perfusion and cyanosis at several days of age is a medical emergency requiring urgent assessment and treatment, not reassurance and discharge.', 2),
('e1000000-0000-0000-0000-000000000019', 'C', 'Start broad-spectrum antibiotics alone and monitor without cardiology input', false, 'Ruled out because although sepsis is an important differential for neonatal collapse and should be covered empirically, the specific features here (differential saturations, poor response to oxygen) point strongly towards duct-dependent cardiac disease, which requires prostaglandin E1 and urgent cardiology involvement alongside any sepsis work-up, not instead of it.', 3),
('e1000000-0000-0000-0000-000000000019', 'D', 'Start a prostaglandin E1 infusion to maintain ductal patency', true, 'Correct. Sudden collapse in an initially well neonate around day 2-5 of life, with poor perfusion, differential saturations, and failure to improve significantly with 100% oxygen (a positive/abnormal hyperoxia test), strongly suggests duct-dependent congenital heart disease presenting as the ductus arteriosus closes physiologically. A prostaglandin E1 infusion is started immediately to maintain or reopen the ductus arteriosus, providing crucial systemic or pulmonary blood flow while arranging urgent echocardiography and specialist cardiology transfer.', 4),
('e1000000-0000-0000-0000-000000000019', 'E', 'Perform immediate closure of the ductus arteriosus surgically', false, $x$Ruled out because the ductus arteriosus is the infant's lifeline in duct-dependent congenital heart disease at this stage; closing it would be catastrophic. The priority is to keep it open with prostaglandin E1, not close it.$x$, 5),
('e1000000-0000-0000-0000-000000000020', 'A', 'Refer urgently for same-day echocardiography', false, 'Ruled out because the described features are entirely consistent with a benign innocent murmur; urgent echocardiography is not warranted in the absence of any red flag features such as a loud murmur, diastolic component, thrill, radiation, or symptoms.', 1),
('e1000000-0000-0000-0000-000000000020', 'B', 'Start prophylactic antibiotics before any future dental procedures', false, 'Ruled out because antibiotic prophylaxis for dental procedures is reserved for specific high-risk structural heart conditions, not innocent murmurs, which carry no increased risk of infective endocarditis.', 2),
('e1000000-0000-0000-0000-000000000020', 'C', 'Advise restriction from all sports and physical activity', false, 'Ruled out because an innocent murmur in an asymptomatic, healthy child with normal examination findings does not warrant any activity restriction.', 3),
('e1000000-0000-0000-0000-000000000020', 'D', 'Admit to hospital for continuous cardiac monitoring', false, 'Ruled out because there is no indication for admission or monitoring in an asymptomatic child with a murmur bearing all the classic reassuring features of an innocent murmur.', 4),
('e1000000-0000-0000-0000-000000000020', 'E', 'Reassure the parents that this is likely an innocent murmur, with no further investigation needed', true, 'Correct. This murmur has the classic features of an innocent (functional) murmur: soft, short, systolic, no radiation, varies with position, and occurs in an asymptomatic, thriving child with an otherwise entirely normal cardiovascular examination. Innocent murmurs are common in childhood and do not require echocardiography or referral when these reassuring features are present.', 5),
('e1000000-0000-0000-0000-000000000021', 'A', 'Continue a further course of oral antibiotics for presumed bacterial tonsillitis', false, 'Ruled out because this clinical picture (prolonged fever unresponsive to antibiotics with conjunctival injection, oral changes, rash, extremity changes, and lymphadenopathy) is not consistent with simple bacterial tonsillitis, and further antibiotics would not address the underlying vasculitic process of Kawasaki disease or prevent coronary complications.', 1),
('e1000000-0000-0000-0000-000000000021', 'B', 'Reassure the parents that this is a self-limiting viral illness requiring only symptomatic treatment', false, 'Ruled out because Kawasaki disease is not simply a self-limiting viral illness; without treatment there is a significant risk of coronary artery aneurysm formation, so specific treatment (IVIG and aspirin) is required, not symptomatic management alone.', 2),
('e1000000-0000-0000-0000-000000000021', 'C', 'Admit for treatment with intravenous immunoglobulin and high-dose aspirin, and arrange an echocardiogram', true, 'Correct. Fever for 5 or more days with at least 4 of: bilateral conjunctival injection, oral/lip changes (cracked lips, strawberry tongue), polymorphous rash, changes in extremities (erythema/oedema), and cervical lymphadenopathy meets criteria for Kawasaki disease. Prompt treatment with intravenous immunoglobulin and high-dose aspirin (within 10 days of fever onset) reduces the risk of coronary artery aneurysms, the most feared complication, and an echocardiogram should be arranged to assess the coronary arteries at diagnosis and during follow-up.', 3),
('e1000000-0000-0000-0000-000000000021', 'D', 'Start oral corticosteroids as first-line treatment instead of intravenous immunoglobulin', false, 'Ruled out because intravenous immunoglobulin plus high-dose aspirin is the established first-line treatment for Kawasaki disease; corticosteroids are generally reserved as an adjunct in IVIG-resistant cases, not as first-line monotherapy.', 4),
('e1000000-0000-0000-0000-000000000021', 'E', 'Discharge home with outpatient follow-up in two weeks', false, 'Ruled out because suspected Kawasaki disease requires admission for prompt treatment (ideally within 10 days of fever onset) and echocardiographic assessment, given the risk of coronary artery aneurysm if treatment is delayed.', 5),
('e1000000-0000-0000-0000-000000000022', 'A', 'Perform an urgent lumbar puncture in all cases before discharge', false, 'Ruled out because a lumbar puncture is not routinely required for a straightforward simple febrile seizure with full recovery and no red flag features; it is reserved for cases with signs of meningitis/encephalitis, prolonged/focal seizures, or in infants where clinical suspicion of CNS infection is higher.', 1),
('e1000000-0000-0000-0000-000000000022', 'B', 'Examine for a source of infection, reassure the parents, and provide safety-netting advice as this is likely a simple febrile seizure', true, 'Correct. A generalised, brief (under 15 minutes) seizure occurring with fever in a child aged 6 months to 6 years, with full and rapid recovery and no focal features, is a simple febrile seizure. Management focuses on identifying and treating the underlying cause of fever, reassurance about the generally benign nature and recurrence risk, and clear safety-netting advice on when to seek urgent review (e.g. prolonged seizure, focal features, reduced consciousness, non-blanching rash).', 2),
('e1000000-0000-0000-0000-000000000022', 'C', 'Start regular prophylactic anticonvulsant medication to prevent recurrence', false, 'Ruled out because prophylactic anticonvulsants are not recommended for simple febrile seizures, which are generally benign and self-limiting; management is directed at the underlying fever and safety-netting rather than long-term antiepileptic prophylaxis.', 3),
('e1000000-0000-0000-0000-000000000022', 'D', 'Admit for continuous EEG monitoring for 24 hours', false, 'Ruled out because a straightforward simple febrile seizure with complete recovery does not require EEG monitoring; EEG is not indicated in the routine work-up of simple febrile seizures.', 4),
('e1000000-0000-0000-0000-000000000022', 'E', 'Diagnose epilepsy and refer for long-term antiepileptic treatment', false, 'Ruled out because a febrile seizure is not equivalent to epilepsy; epilepsy refers to recurrent unprovoked seizures, whereas this seizure occurred specifically in the context of fever, which is a distinct and generally benign entity in this age group.', 5),
('e1000000-0000-0000-0000-000000000023', 'A', 'Wait for blood culture results before starting any antibiotics', false, 'Ruled out because meningococcal septicaemia can progress to death within hours; empirical antibiotics must be given immediately on clinical suspicion, with blood cultures taken at the same time if this does not delay treatment, never withheld pending results.', 1),
('e1000000-0000-0000-0000-000000000023', 'B', 'Perform a lumbar puncture first to confirm the diagnosis before treatment', false, 'Ruled out because lumbar puncture is contraindicated in a shocked, unstable child and must never delay life-saving empirical antibiotics; it may be considered later once the child is stabilised, if at all, given clear contraindications here (shock, non-blanching rash, coagulopathy risk).', 2),
('e1000000-0000-0000-0000-000000000023', 'C', 'Apply topical antiseptic to the rash and monitor for progression', false, 'Ruled out because topical treatment has no role in an invasive, life-threatening bacterial infection; this child needs immediate systemic antibiotics and resuscitation, not local skin care.', 3),
('e1000000-0000-0000-0000-000000000023', 'D', 'Give intravenous (or intramuscular if access is delayed) benzylpenicillin/ceftriaxone immediately and start fluid resuscitation without waiting for investigations', true, 'Correct. A febrile, lethargic child with a non-blanching purpuric rash and signs of shock (tachycardia, poor perfusion, prolonged capillary refill, reduced consciousness) has suspected meningococcal septicaemia until proven otherwise. This is a life-threatening emergency: empirical antibiotics (e.g. ceftriaxone, or benzylpenicillin if in the community) must be given immediately, alongside urgent fluid resuscitation, without waiting for blood tests, lumbar puncture, or senior review to first confirm the diagnosis.', 4),
('e1000000-0000-0000-0000-000000000023', 'E', 'Discharge with oral antibiotics and outpatient follow-up given he is talking and conscious', false, $x$Ruled out because reduced consciousness ('difficult to rouse'), shock, and a non-blanching rash indicate a critically unwell child requiring immediate hospital-based resuscitation and intravenous treatment, not discharge on oral antibiotics.$x$, 5),
('e1000000-0000-0000-0000-000000000024', 'A', 'Give intramuscular adrenaline immediately, lie him flat with legs raised (or sitting up if breathing is the main difficulty), and call for emergency help', true, 'Correct. This presentation (rapid onset of urticaria, angioedema, wheeze/respiratory difficulty, and hypotension after a known allergen exposure) is anaphylaxis. Intramuscular adrenaline into the anterolateral thigh is the immediate first-line treatment and should not be delayed; the child should be positioned appropriately (lying flat with legs raised for hypotension, or sitting up if breathing difficulty predominates, avoiding sudden standing which can cause cardiovascular collapse), with emergency help called and oxygen, fluids, and further doses of adrenaline given as needed.', 1),
('e1000000-0000-0000-0000-000000000024', 'B', 'Give an oral antihistamine and observe for improvement over the next hour', false, 'Ruled out because oral antihistamines act too slowly and are inadequate for anaphylaxis with respiratory and cardiovascular compromise; intramuscular adrenaline is required immediately, with antihistamines only as an adjunct after adrenaline.', 2),
('e1000000-0000-0000-0000-000000000024', 'C', 'Give a nebulised bronchodilator alone and reassess in 15 minutes without adrenaline', false, 'Ruled out because while a bronchodilator may help wheeze as an adjunct, it does not treat the systemic anaphylactic reaction or hypotension; intramuscular adrenaline is the essential first-line treatment and must not be delayed or substituted.', 3),
('e1000000-0000-0000-0000-000000000024', 'D', 'Sit the child upright immediately and encourage him to stand to help him breathe', false, $x$Ruled out because standing or sudden postural changes in anaphylaxis with hypotension can precipitate cardiovascular collapse ('empty ventricle syndrome'); positioning should support circulation (lying flat with legs raised) unless respiratory distress specifically requires sitting up, and adrenaline is the priority regardless of position.$x$, 4),
('e1000000-0000-0000-0000-000000000024', 'E', 'Give intravenous hydrocortisone as the first and only treatment', false, 'Ruled out because corticosteroids have a slow onset of action and are not first-line treatment for acute anaphylaxis; intramuscular adrenaline is the immediate priority, with steroids considered as an adjunct afterward if used at all.', 5),
('e1000000-0000-0000-0000-000000000025', 'A', 'Presence of any stridor at all, since only epiglottitis causes stridor', false, 'Ruled out because both croup and epiglottitis can cause inspiratory stridor; stridor alone does not distinguish between them. The distinguishing features are the toxic appearance, drooling, absence of a barking cough, and rapid onset seen in epiglottitis.', 1),
('e1000000-0000-0000-0000-000000000025', 'B', 'A barking cough, since this is more typical of epiglottitis', false, 'Ruled out because a barking cough is characteristic of croup, not epiglottitis; epiglottitis characteristically lacks a barking cough, which is one of the key distinguishing features.', 2),
('e1000000-0000-0000-0000-000000000025', 'C', 'Age of the child, since epiglottitis only occurs in infants under 1 year', false, 'Ruled out because epiglottitis (classically due to Haemophilus influenzae type b, now rarer with vaccination) can occur across childhood, not exclusively in infants; age alone does not reliably distinguish the two conditions.', 3),
('e1000000-0000-0000-0000-000000000025', 'D', 'Presence of fever, since only epiglottitis causes a fever', false, 'Ruled out because fever is common to both croup and epiglottitis; fever alone does not distinguish between the conditions, though epiglottitis is typically associated with a higher, more rapidly progressive fever alongside toxicity.', 4),
('e1000000-0000-0000-0000-000000000025', 'E', 'Rapid onset of high fever with drooling, reluctance to swallow, and a toxic, anxious appearance without a barking cough', true, 'Correct. Acute epiglottitis classically presents with rapid onset of high fever, a toxic/anxious appearance, drooling due to painful/reluctant swallowing, and soft stridor, notably without the barking cough typical of croup. Croup, in contrast, usually has a more gradual onset with a hoarse, barking cough and stridor that fluctuates with distress. Recognising epiglottitis is critical: it is a life-threatening emergency requiring senior anaesthetic/ENT involvement and avoidance of any distressing examination (including throat inspection) that could precipitate complete airway obstruction.', 5),
('e1000000-0000-0000-0000-000000000026', 'A', 'Cautious intravenous fluid resuscitation with careful monitoring for signs of cerebral oedema, alongside a fixed-rate intravenous insulin infusion', true, 'Correct. This is severe diabetic ketoacidosis (pH <7.1, significant ketosis, hyperglycaemia) with clinical dehydration. In children, fluid resuscitation must be given cautiously and calculated carefully (avoiding excessive or overly rapid fluid administration) because of the specific risk of cerebral oedema in paediatric DKA, alongside starting a fixed-rate intravenous insulin infusion (generally after an initial period of fluid replacement) with close neurological and electrolyte monitoring throughout treatment.', 1),
('e1000000-0000-0000-0000-000000000026', 'B', 'Give a rapid large-volume intravenous fluid bolus to correct dehydration as quickly as possible', false, 'Ruled out because rapid, large-volume fluid boluses in paediatric DKA significantly increase the risk of cerebral oedema, a leading cause of mortality in this condition; fluid replacement must be calculated and given cautiously over a defined period, not as fast as possible.', 2),
('e1000000-0000-0000-0000-000000000026', 'C', 'Start a subcutaneous insulin regimen and manage as an outpatient', false, 'Ruled out because severe DKA with significant acidosis and ketosis is a medical emergency requiring inpatient management with intravenous fluids and an intravenous insulin infusion; subcutaneous insulin and outpatient management are entirely inappropriate at this stage.', 3),
('e1000000-0000-0000-0000-000000000026', 'D', 'Give intravenous sodium bicarbonate immediately to correct the acidosis', false, 'Ruled out because routine bicarbonate administration in paediatric DKA is not recommended, as it does not improve outcomes and may worsen intracellular acidosis and increase the risk of cerebral oedema; acidosis is corrected through fluid and insulin therapy.', 4),
('e1000000-0000-0000-0000-000000000026', 'E', 'Withhold all insulin until the blood glucose falls below 15 mmol/L', false, 'Ruled out because insulin is a core part of DKA treatment to resolve ketosis and acidosis, generally started (at a fixed low rate) once initial fluid resuscitation is underway; withholding it delays resolution of the underlying metabolic derangement rather than being appropriate practice.', 5),
('e1000000-0000-0000-0000-000000000027', 'A', 'Perform abdominal thrusts (Heimlich manoeuvre) immediately', false, 'Ruled out because abdominal thrusts are avoided in infants due to the risk of intra-abdominal organ injury; in infants, back blows and chest thrusts (not abdominal thrusts) are used, and even these are reserved for an ineffective cough or complete obstruction, not while the cough remains effective.', 1),
('e1000000-0000-0000-0000-000000000027', 'B', 'Attempt blind finger sweeps of the mouth to remove the foreign body', false, 'Ruled out because blind finger sweeps risk pushing the foreign body further into the airway and causing further obstruction or trauma; visible objects may be carefully removed if seen, but blind sweeps are not recommended.', 2),
('e1000000-0000-0000-0000-000000000027', 'C', 'Immediately proceed to needle cricothyroidotomy', false, 'Ruled out because this is an extreme, invasive emergency airway procedure reserved for complete obstruction with failure of basic manoeuvres and no other option; it is entirely inappropriate as an initial step in a conscious infant with an effective cough.', 3),
('e1000000-0000-0000-0000-000000000027', 'D', 'Give back blows and chest thrusts even though he is coughing effectively, to dislodge the object proactively', false, 'Ruled out because current guidance recommends observation and encouragement of coughing while the cough remains effective; back blows/chest thrusts are reserved for when the cough becomes ineffective or the child cannot vocalise/breathe, to avoid worsening the obstruction unnecessarily.', 4),
('e1000000-0000-0000-0000-000000000027', 'E', 'Encourage him to continue coughing and closely observe, only intervening with back blows/chest thrusts if the cough becomes ineffective or he stops breathing/making sound', true, 'Correct. This infant has a partial airway obstruction with an effective cough (able to cry/make sound, forceful coughing, maintaining oxygenation). Current guidance is to encourage continued coughing and closely observe, as this is often the most effective way to clear a foreign body, escalating to back blows and chest thrusts (in an infant, not abdominal thrusts) only if the cough becomes ineffective, or if there is loss of consciousness or inability to breathe/vocalise.', 5),
('e1000000-0000-0000-0000-000000000028', 'A', 'Repeat the same dose of buccal midazolam and wait a further 10 minutes before reassessing', false, 'Ruled out because a second dose of the same first-tier benzodiazepine without escalation is not the recommended next step once IV access is available; the priority is to move to intravenous benzodiazepine therapy (lorazepam) promptly given ongoing seizure activity.', 1),
('e1000000-0000-0000-0000-000000000028', 'B', 'Give a loading dose of intravenous phenytoin as the very first-line treatment, skipping benzodiazepines entirely', false, 'Ruled out because phenytoin (or an alternative second-line agent such as levetiracetam or phenobarbital) is used at the next stage of the algorithm if seizures persist after two doses of benzodiazepine, not as the immediate first step in preference to intravenous lorazepam at this point.', 2),
('e1000000-0000-0000-0000-000000000028', 'C', 'Perform an urgent lumbar puncture before giving any further anticonvulsant treatment', false, 'Ruled out because lumbar puncture is not the priority in ongoing status epilepticus; the seizure itself must be terminated urgently with escalating anticonvulsant therapy, and any investigation for an underlying cause follows once the seizure is controlled and the child is stable.', 3),
('e1000000-0000-0000-0000-000000000028', 'D', 'Give intravenous lorazepam', true, 'Correct. This child is in status epilepticus (continuous seizure activity beyond 5 minutes, or failure to regain consciousness between seizures) and has already received one dose of benzodiazepine (buccal midazolam) more than 5 minutes ago without effect. With intravenous access now available, the next step per paediatric status epilepticus algorithms is a dose of intravenous lorazepam (or diazepam), moving to the next stage of the treatment ladder rather than repeating the same initial-tier benzodiazepine route.', 4),
('e1000000-0000-0000-0000-000000000028', 'E', 'Observe without further treatment as the seizure will likely self-terminate', false, 'Ruled out because status epilepticus does not reliably self-terminate and carries risks of hypoxic brain injury the longer it continues; active escalation of treatment is required, not passive observation.', 5),
('e1000000-0000-0000-0000-000000000029', 'A', 'Proceed immediately to pyloromyotomy without correcting fluids first', false, 'Ruled out because operating on a dehydrated infant with significant electrolyte and acid-base derangement carries substantial anaesthetic and metabolic risk; correction of fluids and electrolytes must always precede surgery in pyloric stenosis.', 1),
('e1000000-0000-0000-0000-000000000029', 'B', 'Correct fluid and electrolyte abnormalities with intravenous fluids before any surgical intervention', true, 'Correct. This presentation (projectile, non-bilious vomiting from around 4-6 weeks of age, a palpable olive-shaped pyloric mass, and a hypochloraemic, hypokalaemic metabolic alkalosis from persistent vomiting of gastric contents) is classic for pyloric stenosis. Although pyloromyotomy is curative, it is not an emergency: the essential first step is correcting dehydration and the electrolyte/acid-base abnormalities with intravenous fluids, as proceeding to anaesthesia and surgery in a dehydrated, alkalotic infant carries significant anaesthetic risk (including postoperative apnoea).', 2),
('e1000000-0000-0000-0000-000000000029', 'C', 'Start a proton pump inhibitor and reassess in 2 weeks', false, 'Ruled out because acid suppression does not address the underlying anatomical hypertrophic pyloric obstruction; definitive treatment is surgical (pyloromyotomy) after fluid correction, not medical acid suppression.', 3),
('e1000000-0000-0000-0000-000000000029', 'D', 'Reassure the parents that this is normal reflux and advise smaller, more frequent feeds', false, 'Ruled out because the combination of projectile vomiting, a palpable pyloric mass, and hypochloraemic hypokalaemic alkalosis is not consistent with simple reflux and requires urgent recognition and treatment of pyloric stenosis, not reassurance.', 4),
('e1000000-0000-0000-0000-000000000029', 'E', 'Perform an urgent barium swallow as the definitive diagnostic and next management step', false, 'Ruled out because abdominal ultrasound, not a barium study, is the investigation of choice to confirm pyloric stenosis (showing pyloric muscle thickening and length), and in any case correcting fluids/electrolytes takes priority as the immediate management step before further definitive treatment.', 5),
('e1000000-0000-0000-0000-000000000030', 'A', 'Barium swallow and follow-through', false, 'Ruled out because a barium swallow and follow-through assesses the upper gastrointestinal tract and is not the appropriate first investigation for suspected intussusception; ultrasound is quicker, avoids radiation, and is diagnostic.', 1),
('e1000000-0000-0000-0000-000000000030', 'B', 'Abdominal X-ray as the definitive diagnostic investigation', false, 'Ruled out because while an abdominal X-ray may be used to look for signs of obstruction or free air, it is not sensitive or specific enough to reliably diagnose intussusception; ultrasound is the investigation of choice.', 2),
('e1000000-0000-0000-0000-000000000030', 'C', 'Abdominal ultrasound', true, $x$Correct. Intermittent colicky abdominal pain with drawing up of the legs, lethargy between episodes, redcurrant jelly stool, and a palpable sausage-shaped abdominal mass are classic features of intussusception, most common between 6 months and 2 years of age. Abdominal ultrasound is the first-line investigation, classically showing a 'target' or 'doughnut' sign, and if positive is typically followed by therapeutic air (or contrast) enema reduction under radiological guidance, with surgery reserved for failed reduction or perforation.$x$, 3),
('e1000000-0000-0000-0000-000000000030', 'D', 'Stool culture and sensitivity', false, 'Ruled out because this presentation is a surgical/radiological emergency (intussusception) rather than an infective diarrhoeal illness, and stool culture would not identify or address the underlying mechanical problem.', 4),
('e1000000-0000-0000-0000-000000000030', 'E', 'Upper gastrointestinal endoscopy', false, 'Ruled out because endoscopy is not indicated for suspected intussusception, which occurs in the small/large bowel and is diagnosed and often treated using ultrasound and enema techniques, not endoscopy.', 5),
('e1000000-0000-0000-0000-000000000031', 'A', 'Start a gluten-free diet immediately and use symptomatic improvement to confirm the diagnosis', false, 'Ruled out because starting a gluten-free diet before biopsy confirmation risks normalising the histological changes, making subsequent diagnostic confirmation difficult or impossible; biopsy should be performed first while gluten intake continues.', 1),
('e1000000-0000-0000-0000-000000000031', 'B', 'Advise that no further testing is needed and diagnose coeliac disease based on serology alone in all cases', false, 'Ruled out because although some paediatric guidelines allow a biopsy-sparing pathway with very high antibody titres plus other criteria, standard practice for confirming the diagnosis definitively (particularly outside those strict criteria) is duodenal biopsy; assuming serology alone is always sufficient in every case is not correct as a general rule.', 2),
('e1000000-0000-0000-0000-000000000031', 'C', 'Refer for endoscopy with duodenal biopsy while she continues eating a normal gluten-containing diet', true, 'Correct. Faltering growth, chronic diarrhoea/bloating, and a significantly elevated anti-TTG IgA (with normal total IgA, confirming the test is valid) are highly suggestive of coeliac disease. Current practice is to confirm the diagnosis with endoscopic duodenal biopsy (showing villous atrophy and crypt hyperplasia) while the child continues eating a normal gluten-containing diet, as starting a gluten-free diet before biopsy can normalise the intestinal changes and obscure the diagnosis.', 3),
('e1000000-0000-0000-0000-000000000031', 'D', 'Repeat the anti-TTG test in 6 months without further action', false, 'Ruled out because a significantly elevated anti-TTG with a compatible clinical picture requires prompt further work-up (biopsy) rather than simply repeating serology after a delay, which would prolong ongoing nutritional harm from unrecognised coeliac disease.', 4),
('e1000000-0000-0000-0000-000000000031', 'E', 'Test for Helicobacter pylori as the most likely explanation for her symptoms', false, 'Ruled out because Helicobacter pylori infection does not explain the combination of chronic diarrhoea, faltering growth, and a significantly elevated anti-TTG antibody, which point specifically towards coeliac disease rather than H. pylori-related disease.', 5),
('e1000000-0000-0000-0000-000000000032', 'A', 'Switch to a standard soy-based formula as first-line treatment', false, $x$Ruled out because there is significant cross-reactivity between cow's milk and soy protein, particularly in infants, so soy-based formula is not the recommended first-line alternative; an extensively hydrolysed formula is preferred first-line.$x$, 1),
('e1000000-0000-0000-0000-000000000032', 'B', 'Continue the current formula and start a topical steroid for the eczema only', false, $x$Ruled out because continuing exposure to the suspected allergen (cow's milk protein) while only treating the skin manifestation does not address the underlying gastrointestinal symptoms or the likely causative allergy; formula change should be trialled.$x$, 2),
('e1000000-0000-0000-0000-000000000032', 'C', 'Refer for immediate skin prick testing as the essential first step before any dietary change', false, $x$Ruled out because non-IgE-mediated cow's milk protein allergy (suggested here by gastrointestinal symptoms and eczema without acute IgE-type reactions) is typically diagnosed clinically with a diagnostic dietary exclusion/reintroduction approach rather than skin prick testing, which is more useful for IgE-mediated reactions.$x$, 3),
('e1000000-0000-0000-0000-000000000032', 'D', 'Start empirical oral antibiotics for presumed gastroenteritis', false, 'Ruled out because there is no fever or other feature suggesting an infective cause, and antibiotics would not address the underlying allergic process suggested by the combination of gastrointestinal symptoms and eczema.', 4),
('e1000000-0000-0000-0000-000000000032', 'E', 'Trial an extensively hydrolysed formula and reassess symptoms', true, $x$Correct. Vomiting, blood/mucus-streaked loose stools, irritability after feeds, and eczema in a young formula-fed infant are suggestive of cow's milk protein allergy. First-line management for formula-fed infants with suspected non-IgE-mediated cow's milk protein allergy is a trial of an extensively hydrolysed formula for a defined period, assessing for symptom resolution, with escalation to an amino acid-based formula if symptoms persist.$x$, 5),
('e1000000-0000-0000-0000-000000000033', 'A', 'Reassure the parents that green vomiting is a normal variant in neonates and advise smaller feeds', false, 'Ruled out because bilious (green) vomiting in an infant is never a normal finding and always requires urgent investigation to exclude a surgical cause such as malrotation with volvulus, given the risk of rapid bowel ischaemia.', 1),
('e1000000-0000-0000-0000-000000000033', 'B', 'Urgent surgical referral for emergency laparotomy after initial resuscitation, with an urgent upper GI contrast study if time allows', true, 'Correct. Bilious vomiting in a neonate/young infant is a red flag that must be treated as malrotation with volvulus until proven otherwise, as this is a surgical emergency with a risk of bowel ischaemia and necrosis if the midgut twists around the mesenteric pedicle. Management is urgent resuscitation (fluids, nasogastric decompression) alongside emergency surgical referral, with an upper gastrointestinal contrast study (showing an abnormal duodenal-jejunal flexure position) used to support diagnosis only if it does not delay definitive treatment in a clearly unwell infant.', 2),
('e1000000-0000-0000-0000-000000000033', 'C', 'Start oral rehydration therapy and review in outpatient clinic in one week', false, 'Ruled out because this presentation represents a surgical emergency with risk of bowel necrosis if untreated; outpatient management with a one-week delay would risk catastrophic bowel loss or death.', 3),
('e1000000-0000-0000-0000-000000000033', 'D', 'Give a laxative suppository, as this is likely to be simple constipation', false, 'Ruled out because there is no history of constipation and the infant passed meconium normally; bilious vomiting with abdominal distension and systemic illness is not consistent with simple constipation and instead points to a surgical emergency.', 4),
('e1000000-0000-0000-0000-000000000033', 'E', 'Arrange elective outpatient abdominal ultrasound in the next available slot', false, 'Ruled out because the urgency of this presentation (bilious vomiting with signs of a sick infant) demands immediate resuscitation and same-day surgical assessment/imaging, not an elective outpatient appointment.', 5),
('e1000000-0000-0000-0000-000000000034', 'A', 'Start a proton pump inhibitor immediately as first-line treatment', false, 'Ruled out because acid-suppressing medication is not first-line for simple, uncomplicated reflux in a thriving infant with no signs of complication (such as significant distress, feeding refusal, faltering growth, or oesophagitis); conservative measures are tried first.', 1),
('e1000000-0000-0000-0000-000000000034', 'B', 'Refer urgently for upper gastrointestinal endoscopy', false, 'Ruled out because endoscopy is reserved for infants with red flag features (e.g. haematemesis, dysphagia, faltering growth, persistent symptoms despite conservative measures) and is not indicated for simple, uncomplicated reflux in a thriving infant.', 2),
('e1000000-0000-0000-0000-000000000034', 'C', $x$Advise stopping breastfeeding/formula feeding and switching to thickened cow's milk immediately$x$, false, $x$Ruled out because cow's milk is not an appropriate primary feed before 12 months of age, and switching feeds is not the first-line management for simple reflux; feeding technique/positioning advice and reassurance come first.$x$, 3),
('e1000000-0000-0000-0000-000000000034', 'D', $x$Reassure the parents that this is likely simple gastro-oesophageal reflux ('happy spitter'), with advice on positioning and feeding technique$x$, true, $x$Correct. Frequent small-volume regurgitation ('posseting') in an otherwise thriving, well infant with normal growth and no red flag features (no bilious vomiting, no blood, no faltering growth, no respiratory symptoms, no distress suggesting significant discomfort) is typical of simple, physiological gastro-oesophageal reflux, extremely common in infancy. Initial management is reassurance and simple advice (smaller, more frequent feeds, upright positioning after feeds, review of feeding technique), which usually resolves by 12 months as the infant matures.$x$, 4),
('e1000000-0000-0000-0000-000000000034', 'E', 'Admit to hospital for observation and investigation', false, 'Ruled out because a thriving, well infant with simple, uncomplicated reflux does not require hospital admission; this can be managed safely with reassurance and advice in primary care.', 5),
('e1000000-0000-0000-0000-000000000035', 'A', 'Toddler diarrhoea (chronic non-specific diarrhoea of childhood)', true, 'Correct. Frequent loose stools containing undigested food particles in an otherwise well, thriving toddler with normal growth and no alarm features (no blood, no nocturnal symptoms, no weight faltering) is classic for toddler diarrhoea, a common, benign, self-limiting condition thought to relate to rapid gut transit. Management is reassurance and simple dietary advice (adequate fat intake, avoiding excessive fruit juice/sugary drinks), with resolution typically by school age.', 1),
('e1000000-0000-0000-0000-000000000035', 'B', 'Coeliac disease', false, 'Ruled out because coeliac disease typically causes faltering growth and other systemic features alongside gastrointestinal symptoms, whereas this child is thriving with normal growth along a good centile, which is reassuring against a malabsorptive process.', 2),
('e1000000-0000-0000-0000-000000000035', 'C', 'Cystic fibrosis with pancreatic insufficiency', false, 'Ruled out because cystic fibrosis with pancreatic insufficiency typically causes steatorrhoea (pale, offensive, fatty stools) along with faltering growth and often respiratory symptoms, which are absent here in a thriving, well child.', 3),
('e1000000-0000-0000-0000-000000000035', 'D', 'Inflammatory bowel disease', false, 'Ruled out because inflammatory bowel disease typically presents with blood/mucus in stool, weight loss or faltering growth, abdominal pain, and sometimes systemic symptoms, none of which are described in this thriving, well toddler.', 4),
('e1000000-0000-0000-0000-000000000035', 'E', 'Giardiasis', false, 'Ruled out because giardiasis typically causes more significant symptoms such as bloating, flatulence, and can cause faltering growth or malabsorption, and there is no relevant travel or exposure history here; the clinical picture fits far better with benign toddler diarrhoea.', 5),
('e1000000-0000-0000-0000-000000000036', 'A', 'Amber (intermediate risk)', false, 'Ruled out because amber features include things such as pallor, reduced activity, poor feeding, tachypnoea/tachycardia above specific age-based thresholds, reduced urine output, or fever for 5 days or more, none of which are present in this alert, well-hydrated, appropriately observed child.', 1),
('e1000000-0000-0000-0000-000000000036', 'B', 'Red (high risk)', false, 'Ruled out because red features include signs such as pale/mottled/ashen/blue skin, reduced consciousness, bulging fontanelle, non-blanching rash, focal seizures, or significant respiratory distress, none of which are present in this well-appearing, interactive child.', 2),
('e1000000-0000-0000-0000-000000000036', 'C', 'Cannot be classified without a blood test', false, 'Ruled out because the NICE traffic light system is a clinical assessment tool based on history and examination findings (colour, activity, respiratory, hydration, and other features), not one that requires blood tests to categorise risk.', 3),
('e1000000-0000-0000-0000-000000000036', 'D', 'Amber, purely because she has a fever above 38C', false, 'Ruled out because fever height alone (in a child over 3 months) is not by itself an amber or red criterion in the traffic light system; it is the constellation of clinical features (activity, colour, hydration, respiratory findings, and specific red/amber signs) that determines risk category.', 4),
('e1000000-0000-0000-0000-000000000036', 'E', 'Green (low risk)', true, $x$Correct. Normal colour, alert and responsive with normal social interaction, normal skin/eyes/mucous membranes, and no amber or red features (normal respiratory rate and heart rate for age, normal capillary refill, no focal signs of serious infection) place this child in the 'green' low-risk category of the NICE traffic light system, appropriate for safety-netting and management in the community if a source of fever (e.g. viral upper respiratory tract infection) is identified.$x$, 5),
('e1000000-0000-0000-0000-000000000037', 'A', 'Reassure the parents that this is a viral illness and no urine testing is needed', false, 'Ruled out because urinary tract infection is an important and treatable cause of fever without an obvious focus in infants and must be actively excluded with urine testing, not assumed to be simply viral without investigation.', 1),
('e1000000-0000-0000-0000-000000000037', 'B', 'Start antibiotics without sending any urine sample', false, 'Ruled out because a urine sample for culture should always be sent (ideally before starting antibiotics) to confirm the diagnosis, identify the organism, and guide antibiotic choice/duration and any subsequent imaging decisions.', 2),
('e1000000-0000-0000-0000-000000000037', 'C', 'Send a urine sample for microscopy, culture, and sensitivity, and start empirical antibiotics pending results', true, 'Correct. In an infant with fever without an obvious source, urinary tract infection must always be actively considered and excluded, as it is a common cause of fever in this age group and can be associated with underlying renal tract abnormality. A positive dipstick for leucocytes and nitrites in this context is suggestive of UTI; a clean urine sample should be sent for culture to confirm the diagnosis and guide/refine treatment, with empirical antibiotics started promptly given the positive dipstick and clinical suspicion, without waiting for culture confirmation.', 3),
('e1000000-0000-0000-0000-000000000037', 'D', 'Delay treatment until formal culture results are available in 48 hours', false, 'Ruled out because a positive dipstick with clinical suspicion of UTI in a young febrile infant warrants prompt empirical antibiotic treatment rather than waiting 48 hours for culture confirmation, given the risk of ongoing infection and potential for pyelonephritis/renal scarring.', 4),
('e1000000-0000-0000-0000-000000000037', 'E', 'Arrange an outpatient renal ultrasound as the immediate next step, with no other action', false, 'Ruled out because imaging is part of the follow-up work-up after a confirmed UTI (depending on age, response to treatment, and recurrence), not the immediate next step; the priority now is sending a urine culture and starting treatment for the suspected acute infection.', 5),
('e1000000-0000-0000-0000-000000000038', 'A', 'Withhold antibiotics until lumbar puncture results are available to avoid affecting culture yield', false, 'Ruled out because withholding antibiotics in suspected bacterial meningitis risks rapid deterioration and worse outcomes; empirical antibiotics must be started immediately on clinical suspicion, with lumbar puncture performed as soon as safely possible afterward if it does not delay treatment.', 1),
('e1000000-0000-0000-0000-000000000038', 'B', 'Start empirical intravenous antibiotics without delay, and perform a lumbar puncture promptly if there are no contraindications', true, 'Correct. A bulging fontanelle, lethargy, high-pitched cry, and fever in an infant are concerning features for bacterial meningitis. Empirical intravenous antibiotics (e.g. ceftriaxone/cefotaxime, with amoxicillin added in young infants to cover Listeria) should be started immediately without waiting for lumbar puncture results, and lumbar puncture should be performed promptly to identify the causative organism and guide ongoing treatment, since there are no contraindications present in this case.', 2),
('e1000000-0000-0000-0000-000000000038', 'C', 'Perform a CT head before considering any antibiotics or lumbar puncture', false, 'Ruled out because CT head is not routinely required before lumbar puncture unless there are specific clinical signs suggesting a contraindication (e.g. focal neurology, papilloedema, reduced consciousness with signs of raised ICP); here there are no contraindications described, so this would only delay essential treatment unnecessarily.', 3),
('e1000000-0000-0000-0000-000000000038', 'D', 'Manage as an outpatient with oral antibiotics and review in 48 hours', false, 'Ruled out because suspected bacterial meningitis is a medical emergency requiring immediate inpatient assessment and intravenous, not oral, antibiotic treatment; outpatient management with delayed review is unsafe.', 4),
('e1000000-0000-0000-0000-000000000038', 'E', 'Give only antipyretics and observe, as a bulging fontanelle is a normal finding in infants with fever', false, 'Ruled out because a bulging fontanelle in the context of fever, lethargy, and irritability is a red flag for raised intracranial pressure/meningitis, not a normal finding, and requires urgent treatment, not simple antipyretic management.', 5),
('e1000000-0000-0000-0000-000000000039', 'A', 'Reassure her that chickenpox exposure in pregnancy is never a concern', false, 'Ruled out because varicella infection in a susceptible pregnant woman carries real risks to both mother and baby depending on gestation, so exposure must be taken seriously and immunity status actively checked, not dismissed as never a concern.', 1),
('e1000000-0000-0000-0000-000000000039', 'B', 'Vaccinate her against varicella immediately with the live attenuated vaccine', false, 'Ruled out because the live attenuated varicella vaccine is contraindicated in pregnancy; if she is found to be non-immune, management is with varicella-zoster immunoglobulin or antiviral treatment as appropriate, not live vaccination.', 2),
('e1000000-0000-0000-0000-000000000039', 'C', 'Advise her to avoid her son for the next 24 hours only, then resume normal contact with no further action', false, 'Ruled out because the significant exposure has already occurred, and the priority now is checking her immunity status to determine whether post-exposure prophylaxis is needed, not simply advising temporary avoidance going forward.', 3),
('e1000000-0000-0000-0000-000000000039', 'D', 'Check her varicella immunity status urgently (history or blood test for varicella IgG), as susceptible pregnant women require specific management after exposure', true, 'Correct. Varicella (chickenpox) infection in pregnancy carries risks to both mother (severe maternal varicella pneumonia) and fetus (congenital varicella syndrome if infected in early pregnancy, or severe neonatal varicella if infection occurs around delivery). The first step after a significant exposure in a pregnant woman of uncertain immunity is to urgently check her varicella immunity (prior history of clear chickenpox is usually sufficient evidence of immunity; if uncertain, a blood test for varicella IgG is checked), as this determines whether post-exposure prophylaxis (varicella-zoster immunoglobulin or antiviral treatment, per current guidance) is needed.', 4),
('e1000000-0000-0000-0000-000000000039', 'E', 'Start empirical oral aciclovir immediately without checking her immunity status', false, 'Ruled out because management should first establish whether she is actually susceptible (non-immune) to varicella, since a woman with confirmed prior infection or immunity does not need prophylaxis; empirical treatment without checking immunity status is not the correct approach.', 5),
('e1000000-0000-0000-0000-000000000040', 'A', 'Start oral phenoxymethylpenicillin (penicillin V) for 10 days and notify public health', true, 'Correct. Fever, sore throat, a fine sandpaper-textured rash with perioral sparing, strawberry tongue, and cervical lymphadenopathy are classic for scarlet fever, caused by an exotoxin-producing Group A streptococcus (usually associated with streptococcal pharyngitis). First-line treatment is a 10-day course of oral penicillin V (or an alternative such as a macrolide if penicillin-allergic) to reduce symptom duration, transmission, and the risk of complications such as rheumatic fever and post-streptococcal glomerulonephritis; scarlet fever is also a notifiable disease requiring public health notification.', 1),
('e1000000-0000-0000-0000-000000000040', 'B', 'Manage supportively with antipyretics alone, as this is a self-limiting viral illness', false, 'Ruled out because scarlet fever is caused by a bacterial (Group A streptococcal) infection, not a virus, and antibiotic treatment is recommended to reduce complications (rheumatic fever, glomerulonephritis) and transmission, not just supportive care alone.', 2),
('e1000000-0000-0000-0000-000000000040', 'C', 'Start oral aciclovir as first-line treatment', false, 'Ruled out because aciclovir is an antiviral agent and has no role in the treatment of scarlet fever, which is a bacterial (streptococcal) infection requiring antibiotics.', 3),
('e1000000-0000-0000-0000-000000000040', 'D', 'Reassure the parents that no treatment or notification is required', false, 'Ruled out because scarlet fever should be treated with antibiotics to reduce complication and transmission risk, and it is a notifiable disease in the UK requiring public health notification, so neither treatment nor notification can be omitted.', 4),
('e1000000-0000-0000-0000-000000000040', 'E', 'Admit for intravenous antibiotics as first-line treatment in all cases', false, 'Ruled out because most children with scarlet fever can be managed as outpatients with oral antibiotics; intravenous treatment and admission are reserved for those who are systemically unwell or unable to tolerate oral treatment, not as a routine first-line approach.', 5),
('e1000000-0000-0000-0000-000000000041', 'A', 'Reassure her that there is no risk to the pregnancy from this exposure', false, 'Ruled out because parvovirus B19 infection in pregnancy carries a genuine, recognised risk of fetal anaemia and hydrops fetalis, particularly in the first half of pregnancy, so exposure cannot be dismissed as risk-free and needs assessment.', 1),
('e1000000-0000-0000-0000-000000000041', 'B', 'Advise that the child remains infectious now and should be isolated from her mother going forward', false, 'Ruled out because children with parvovirus B19 are infectious during the preceding febrile/prodromal phase, before the characteristic rash appears; by the time the rash is visible, the child is no longer considered infectious, so isolation now would not change the exposure risk that has already occurred.', 2),
('e1000000-0000-0000-0000-000000000041', 'C', 'Advise the mother to receive the MMR vaccine as post-exposure prophylaxis', false, 'Ruled out because MMR vaccine protects against measles, mumps, and rubella, not parvovirus B19, and is not relevant post-exposure prophylaxis for this infection; furthermore, live vaccines are generally avoided in pregnancy.', 3),
('e1000000-0000-0000-0000-000000000041', 'D', 'Advise that she should have her varicella-unrelated exposure risk assessed for parvovirus B19, as infection in pregnancy carries a risk of fetal hydrops and should be discussed promptly with her obstetric team', true, $x$Correct. The child's presentation (slapped cheek rash followed by a lacy reticular rash, preceded by a mild febrile illness) is classic for parvovirus B19 infection (erythema infectiosum/fifth disease). By the time the characteristic rash appears, the child is no longer infectious, but the mother's exposure occurred during the preceding febrile/infectious phase. Parvovirus B19 infection in pregnancy carries a risk of fetal anaemia, hydrops fetalis, and (rarely) fetal loss, particularly if infection occurs in the first half of pregnancy, so maternal exposure should be assessed (e.g. checking her immunity/serology) and discussed promptly with her obstetric team for appropriate monitoring.$x$, 4),
('e1000000-0000-0000-0000-000000000041', 'E', 'Advise that this rash is due to varicella and manage exposure risk accordingly', false, 'Ruled out because the described rash (slapped cheek followed by a lacy, reticular pattern) is characteristic of parvovirus B19, not varicella (which causes vesicular, itchy spots at different stages); the exposure risk and management considerations differ between these infections.', 5),
('e1000000-0000-0000-0000-000000000042', 'A', 'Pertussis (whooping cough)', true, $x$Correct. A preceding coryzal (catarrhal) phase followed by paroxysmal coughing bouts, an inspiratory 'whoop', and apnoeic episodes (particularly dangerous and can be the predominant feature in young infants, who may not always whoop) in an incompletely immunised infant is classic for pertussis caused by Bordetella pertussis. This is a notifiable disease; young infants are at particular risk of severe disease including apnoea, pneumonia, and encephalopathy, and macrolide antibiotics (e.g. azithromycin/clarithromycin) are used for the infant and prophylaxis is considered for close contacts, alongside public health notification.$x$, 1),
('e1000000-0000-0000-0000-000000000042', 'B', 'Bronchiolitis', false, 'Ruled out because bronchiolitis typically causes wheeze, crackles, and increased work of breathing over a shorter timeframe without the characteristic paroxysmal coughing bouts with a whoop or the prolonged catarrhal-then-paroxysmal pattern described here.', 2),
('e1000000-0000-0000-0000-000000000042', 'C', 'Croup', false, 'Ruled out because croup causes a barking cough with stridor, typically of more acute onset, and does not classically cause paroxysmal coughing fits with a whoop and apnoeic episodes over this timeframe.', 3),
('e1000000-0000-0000-0000-000000000042', 'D', 'Foreign body aspiration', false, 'Ruled out because there is no history of a choking episode or acute onset with a single object, and the described prodrome (10 days of coryza progressing to paroxysmal whooping cough) fits an infective process (pertussis), not an inhaled foreign body.', 4),
('e1000000-0000-0000-0000-000000000042', 'E', 'Viral-induced wheeze', false, 'Ruled out because viral-induced wheeze presents with audible wheeze during viral infections, not the specific paroxysmal coughing bouts with an inspiratory whoop and apnoea described here, which are characteristic of pertussis.', 5),
('e1000000-0000-0000-0000-000000000043', 'A', 'Start oral antibiotics for a likely bacterial chest infection', false, 'Ruled out because bronchiolitis is a viral illness (most commonly RSV), and antibiotics have no role unless there is a specific concomitant bacterial infection; the priority is supportive care, not antibiotics.', 1),
('e1000000-0000-0000-0000-000000000043', 'B', 'Admit for supportive management, including supplemental oxygen and consideration of nasogastric/intravenous fluids', true, 'Correct. This presentation (young infant, preceding coryza progressing to cough, crackles/wheeze on auscultation, and respiratory distress) is classic for bronchiolitis, most commonly caused by respiratory syncytial virus (RSV). Admission is appropriate given the reduced oxygen saturation (below typical safe thresholds), reduced feeding (less than 50-75% of normal intake is a common admission threshold), and signs of respiratory distress; management is supportive (oxygen if saturations are low, nasogastric or intravenous fluids if feeding is inadequate), as there is no specific antiviral or bacterial treatment for bronchiolitis.', 2),
('e1000000-0000-0000-0000-000000000043', 'C', 'Prescribe a course of inhaled corticosteroids and discharge with follow-up', false, 'Ruled out because corticosteroids (inhaled or systemic) have no proven benefit in bronchiolitis and are not recommended; supportive care is the mainstay of treatment.', 3),
('e1000000-0000-0000-0000-000000000043', 'D', 'Give a nebulised bronchodilator (salbutamol) and discharge home', false, 'Ruled out because bronchodilators have not been shown to be effective in bronchiolitis and are not routinely recommended; given his hypoxia and reduced feeding, discharge would also be inappropriate as he meets criteria for admission.', 4),
('e1000000-0000-0000-0000-000000000043', 'E', 'Reassure the parents that this is a mild viral illness and no follow-up or intervention is needed', false, 'Ruled out because his oxygen saturation of 93% and reduced feeding (60% of normal intake) with respiratory distress indicate he needs admission for supportive management, not simple reassurance and discharge.', 5),
('e1000000-0000-0000-0000-000000000044', 'A', 'Asthma', false, 'Ruled out because asthma is typically characterised by wheeze that also occurs between viral infections (e.g. with exercise, allergen exposure, or at night), often alongside atopic features (eczema, allergic rhinitis, family history); this child has no interval symptoms or atopic triggers, favouring viral-induced wheeze instead.', 1),
('e1000000-0000-0000-0000-000000000044', 'B', 'Bronchiolitis', false, 'Ruled out because bronchiolitis is a single, acute illness typically occurring in infants under 12 months, not a recurrent pattern of episodic wheeze occurring only with viral infections in an older, otherwise well child of this age.', 2),
('e1000000-0000-0000-0000-000000000044', 'C', 'Viral-induced wheeze', true, 'Correct. Episodic wheeze occurring exclusively during viral upper respiratory tract infections, with complete resolution and normal respiratory status between episodes, and no interval symptoms or atopic features, is characteristic of viral-induced (episodic) wheeze, a common pattern in preschool children that often improves with age as the airways grow.', 3),
('e1000000-0000-0000-0000-000000000044', 'D', 'Foreign body aspiration', false, 'Ruled out because foreign body aspiration typically causes a sudden onset of unilateral wheeze or respiratory symptoms following a choking episode, not a recurrent pattern of wheeze specifically associated with viral illnesses over several months.', 4),
('e1000000-0000-0000-0000-000000000044', 'E', 'Cystic fibrosis', false, 'Ruled out because cystic fibrosis typically presents with additional features such as faltering growth, recurrent chest infections, and malabsorptive symptoms, none of which are described in this thriving child with isolated viral-triggered wheeze.', 5),
('e1000000-0000-0000-0000-000000000045', 'A', 'Reassure the family that this is mild and no treatment is needed as she is not cyanosed', false, 'Ruled out because a peak flow of 55% predicted and widespread wheeze represent a significant (moderate-to-severe) exacerbation requiring active bronchodilator and corticosteroid treatment, not simple reassurance, even though there are no life-threatening features currently.', 1),
('e1000000-0000-0000-0000-000000000045', 'B', 'Start a long-acting beta-2 agonist alone for immediate symptom relief', false, 'Ruled out because long-acting beta-2 agonists are not appropriate for acute rescue treatment of an asthma exacerbation; short-acting beta-2 agonists (salbutamol) are used for acute bronchodilation, with LABAs reserved for long-term maintenance control alongside inhaled corticosteroids.', 2),
('e1000000-0000-0000-0000-000000000045', 'C', 'Proceed immediately to intubation and ventilation', false, 'Ruled out because there are no life-threatening features here (no silent chest, cyanosis, exhaustion, or severe hypoxia), so escalation directly to intubation and ventilation is not appropriate; first-line treatment with bronchodilators and steroids should be tried, reserving invasive ventilation for those failing maximal medical therapy with life-threatening features.', 3),
('e1000000-0000-0000-0000-000000000045', 'D', 'Give a single dose of intramuscular adrenaline', false, 'Ruled out because intramuscular adrenaline is the treatment for anaphylaxis, not an asthma exacerbation without features of anaphylaxis (no urticaria, angioedema, or exposure to a trigger allergen described); bronchodilators and steroids are the appropriate treatment here.', 4),
('e1000000-0000-0000-0000-000000000045', 'E', 'Give high-dose inhaled or nebulised salbutamol via a spacer or nebuliser, and a course of oral corticosteroids', true, 'Correct. This is a moderate-to-severe acute asthma exacerbation (peak flow 33-75% predicted without life-threatening features such as silent chest, cyanosis, exhaustion, or severe hypoxia). Immediate management is high-dose short-acting beta-2 agonist (salbutamol), delivered via a spacer with repeated doses or nebuliser depending on severity/response, alongside a course of oral corticosteroids (e.g. prednisolone) to reduce airway inflammation and reduce risk of relapse, with reassessment of response guiding further escalation (e.g. ipratropium, IV therapies) if needed.', 5),
('e1000000-0000-0000-0000-000000000046', 'A', 'Arrange a chest X-ray as an essential step before starting any treatment', false, 'Ruled out because a chest X-ray is not routinely needed to diagnose or guide treatment of straightforward community-acquired pneumonia managed in the outpatient setting; clinical diagnosis based on history and examination is sufficient in a child who is well enough for oral treatment.', 1),
('e1000000-0000-0000-0000-000000000046', 'B', 'Start intravenous co-amoxiclav as first-line treatment for this presentation', false, 'Ruled out because this child, though tachypnoeic, is alert, drinking adequately, and maintaining oxygen saturation of 95% without severe distress; she can be managed with oral antibiotics as an outpatient rather than requiring intravenous treatment and admission.', 2),
('e1000000-0000-0000-0000-000000000046', 'C', 'Manage supportively with antipyretics alone, as pneumonia in children generally does not require antibiotics', false, 'Ruled out because bacterial pneumonia (the most likely cause of this focal, high-fever presentation) requires antibiotic treatment; antipyretics alone would not address the underlying infection.', 3),
('e1000000-0000-0000-0000-000000000046', 'D', 'Diagnose community-acquired pneumonia clinically and start oral amoxicillin', true, 'Correct. Fever, tachypnoea, and focal chest signs (reduced air entry, bronchial breathing, crackles localised to one area) are sufficient to make a clinical diagnosis of pneumonia in children; chest X-ray is not routinely required to confirm the diagnosis if the child can be managed as an outpatient. First-line oral antibiotic treatment for community-acquired pneumonia in children is amoxicillin, reserving admission and intravenous treatment for those who are more unwell, hypoxic, unable to tolerate oral treatment, or with signs of complication.', 4),
('e1000000-0000-0000-0000-000000000046', 'E', 'Prescribe a macrolide antibiotic as first-line treatment in preference to amoxicillin', false, 'Ruled out because amoxicillin remains first-line for community-acquired pneumonia in children of this age; macrolides are typically reserved for atypical pathogen coverage (e.g. suspected Mycoplasma, more common in older children), penicillin allergy, or failure to respond to first-line treatment.', 5),
('e1000000-0000-0000-0000-000000000047', 'A', 'Sweat chloride test', true, 'Correct. Recurrent chest infections, steatorrhoea (greasy, offensive stools reflecting pancreatic exocrine insufficiency), and faltering growth despite a good appetite are classic features of cystic fibrosis, particularly relevant here as this child missed newborn screening. The sweat chloride test (demonstrating elevated chloride concentration in sweat) remains the gold-standard diagnostic test, supported by genetic testing for CFTR mutations.', 1),
('e1000000-0000-0000-0000-000000000047', 'B', 'Barium swallow and follow-through', false, 'Ruled out because a barium study assesses upper gastrointestinal anatomy and does not diagnose cystic fibrosis or explain the underlying pancreatic insufficiency and respiratory features described.', 2),
('e1000000-0000-0000-0000-000000000047', 'C', 'Skin prick allergy testing', false, 'Ruled out because this presentation (recurrent chest infections, steatorrhoea, faltering growth) is not primarily an allergic process, and skin prick testing would not identify or confirm cystic fibrosis.', 3),
('e1000000-0000-0000-0000-000000000047', 'D', 'Anti-tissue transglutaminase (anti-TTG) antibody testing', false, 'Ruled out because although coeliac disease can cause faltering growth and diarrhoea, it does not explain the recurrent chest infections in this vignette; the combined respiratory and pancreatic insufficiency picture points specifically towards cystic fibrosis, for which sweat testing is the key investigation.', 4),
('e1000000-0000-0000-0000-000000000047', 'E', 'Bronchoscopy with bronchoalveolar lavage', false, 'Ruled out because bronchoscopy may have a role later in managing complications of confirmed cystic fibrosis, but it is not the investigation used to establish the initial diagnosis; sweat chloride testing is the appropriate diagnostic test here.', 5),
('e1000000-0000-0000-0000-000000000048', 'A', 'Reassure the parents that this will likely clear on its own and review in one week', false, 'Ruled out because a retained foreign body in the airway will not typically clear spontaneously and carries a risk of complications the longer it remains in place; this requires urgent bronchoscopic removal, not a delayed review.', 1),
('e1000000-0000-0000-0000-000000000048', 'B', 'Start a course of oral antibiotics and inhaled corticosteroids for presumed asthma exacerbation', false, 'Ruled out because unilateral, localised wheeze following a sudden choking episode is not typical of asthma (which usually causes bilateral, widespread wheeze); this clinical picture points specifically to foreign body aspiration, requiring bronchoscopic evaluation, not asthma treatment.', 2),
('e1000000-0000-0000-0000-000000000048', 'C', 'Refer urgently for rigid bronchoscopy under general anaesthesia', true, 'Correct. A sudden coughing/choking episode followed by unilateral, localised wheeze and reduced air entry on one side in a young child (a classic age for putting small objects in the mouth) is strongly suggestive of foreign body aspiration lodged in a main bronchus. Even when the child appears well between episodes, this requires urgent referral for rigid bronchoscopy under general anaesthesia for both diagnostic confirmation and removal, as delayed removal risks complications such as infection, atelectasis, or bronchiectasis.', 3),
('e1000000-0000-0000-0000-000000000048', 'D', 'Arrange elective outpatient chest X-ray in 4 weeks', false, 'Ruled out because a suspected retained foreign body is an urgent problem requiring same-admission assessment and bronchoscopic removal; a 4-week delay for an outpatient X-ray risks ongoing airway complications.', 4),
('e1000000-0000-0000-0000-000000000048', 'E', 'Give nebulised salbutamol and discharge if the wheeze improves', false, 'Ruled out because bronchodilators do not address a mechanical foreign body obstruction, and any transient symptomatic improvement should not be used as a reason to discharge a child with a strongly suspicious history and unilateral examination findings for aspiration.', 5),
('e1000000-0000-0000-0000-000000000049', 'A', 'Reassure the parents that snoring is normal in children and no referral is needed', false, 'Ruled out because although simple snoring without other features can be benign, the combination of witnessed apnoeic episodes, gasping, and daytime symptoms here suggests obstructive sleep apnoea, which requires assessment and cannot simply be reassured away.', 1),
('e1000000-0000-0000-0000-000000000049', 'B', 'Start a nasal corticosteroid spray as the only intervention required', false, 'Ruled out because while nasal steroids can have a role in milder adenoidal hypertrophy or allergic rhinitis contributing to obstruction, the described severity here (large tonsils nearly meeting in the midline, witnessed apnoea, daytime symptoms) warrants ENT referral for consideration of surgical management rather than medical treatment alone.', 2),
('e1000000-0000-0000-0000-000000000049', 'C', 'Arrange a CT scan of the chest to assess for a structural airway abnormality', false, 'Ruled out because the clinical findings (large tonsils, adenoidal facies, snoring with apnoeic episodes) point to an upper airway cause readily assessed clinically and by ENT, not a chest pathology requiring CT chest imaging.', 3),
('e1000000-0000-0000-0000-000000000049', 'D', 'Advise weight loss as the sole management strategy', false, $x$Ruled out because although obesity is a risk factor for obstructive sleep apnoea, this child's presentation is explained by adenotonsillar hypertrophy (large tonsils, adenoidal facies) rather than obesity, and there is no mention of him being overweight; ENT referral for the anatomical cause is the appropriate step.$x$, 4),
('e1000000-0000-0000-0000-000000000049', 'E', 'Refer to ENT for assessment for adenotonsillectomy', true, 'Correct. Loud snoring, witnessed apnoeic episodes with gasping, and daytime symptoms (irritability, poor concentration) in the context of markedly enlarged tonsils are suggestive of obstructive sleep apnoea secondary to adenotonsillar hypertrophy, the most common cause in children of this age. Referral to ENT for assessment, which may include a sleep study depending on severity and local pathways, and consideration of adenotonsillectomy (which is generally curative for this cause) is the appropriate next step.', 5),
('e1000000-0000-0000-0000-000000000050', 'A', 'Start empirical oral antibiotics for a presumed bacterial cause', false, 'Ruled out because croup is caused by a virus, and antibiotics have no role in its management unless there is a specific concern for bacterial superinfection or an alternative bacterial diagnosis (e.g. epiglottitis or bacterial tracheitis), neither of which is suggested by this well, non-toxic child.', 1),
('e1000000-0000-0000-0000-000000000050', 'B', 'Give a single dose of oral dexamethasone', true, $x$Correct. Hoarse voice, barking ('seal-like') cough, and inspiratory stridor with mild recession in a systemically well, non-toxic toddler is classic for croup (viral laryngotracheobronchitis), most commonly caused by parainfluenza virus. A single dose of oral dexamethasone is recommended for children with croup of any severity, as it reduces symptom severity and duration and reduces the likelihood of further healthcare visits or need for escalation; most children can then be managed at home with safety-netting advice.$x$, 2),
('e1000000-0000-0000-0000-000000000050', 'C', 'Examine the throat directly with a tongue depressor to look for epiglottic swelling', false, $x$Ruled out because direct examination of the throat/epiglottis is avoided in a child with stridor due to the risk of precipitating complete airway obstruction if epiglottitis is present; this child's clinical picture (barking cough, hoarse voice, non-toxic appearance, no drooling) in any case favours croup over epiglottitis, and management should proceed without instrumenting the airway.$x$, 3),
('e1000000-0000-0000-0000-000000000050', 'D', 'Admit routinely to intensive care for continuous monitoring', false, 'Ruled out because most children with croup, including those with mild-moderate stridor and recession who remain alert and able to drink, can be managed with oral dexamethasone and observation, without needing intensive care admission; escalation is reserved for severe or deteriorating cases.', 4),
('e1000000-0000-0000-0000-000000000050', 'E', 'Give nebulised adrenaline as the first-line and only treatment required', false, $x$Ruled out because nebulised adrenaline is reserved for moderate-to-severe croup with significant respiratory distress at rest, providing short-term relief while awaiting the effect of steroids; oral dexamethasone is recommended for croup at any severity as a foundational treatment, and this child's presentation (mild recession, alert, drinking) does not clearly require nebulised adrenaline as an immediate first-line step.$x$, 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('e1000000-0000-0000-0000-000000000001', 'Bruising in a non-mobile infant (unable to roll, crawl, or walk) is inherently suspicious, as accidental bruising requires independent mobility.', 1),
('e1000000-0000-0000-0000-000000000001', 'Bruises of differing colours/ages, or on soft-tissue sites (trunk, ears, buttocks, cheeks) rather than bony prominences (shins, forehead), raise concern for non-accidental injury.', 2),
('e1000000-0000-0000-0000-000000000001', 'Any suspicion of abuse warrants urgent same-day safeguarding referral, senior paediatric review, and consideration of a skeletal survey; timely action takes priority over completing every differential first.', 3),
('e1000000-0000-0000-0000-000000000002', 'Independent walking is expected by 15 months, with 18 months as an upper limit of normal; failure by then warrants assessment.', 1),
('e1000000-0000-0000-0000-000000000002', 'A plateau or regression in previously acquired skills (here, no new words since 12 months) is more concerning than simple slowness and should never be reassured away.', 2),
('e1000000-0000-0000-0000-000000000002', 'Delay in more than one developmental domain (here, gross motor and language) increases the likelihood of a significant underlying disorder and strengthens the case for formal assessment.', 3),
('e1000000-0000-0000-0000-000000000003', 'Constitutional delay of growth and puberty shows a growth curve running parallel to (not crossing) a centile line, with bone age delay proportionate to the height delay.', 1),
('e1000000-0000-0000-0000-000000000003', $x$A family history of 'late developers' strongly supports a constitutional pattern and is reassuring; management is watchful waiting with growth monitoring, not endocrine treatment.$x$, 2),
('e1000000-0000-0000-0000-000000000003', 'A falling growth velocity that crosses centiles downward should always prompt investigation for an organic cause (e.g. growth hormone deficiency, hypothyroidism, coeliac disease) rather than being assumed constitutional.', 3),
('e1000000-0000-0000-0000-000000000004', 'Metaphyseal (corner/bucket-handle) fractures, posterior rib fractures, and multiple fractures of different ages are among the injury patterns most specific for non-accidental injury.', 1),
('e1000000-0000-0000-0000-000000000004', 'A fracture with no plausible mechanism in a non- or pre-mobile infant should always trigger a skeletal survey and safeguarding referral, run in parallel with (not delayed by) exclusion of medical mimics such as osteogenesis imperfecta.', 2),
('e1000000-0000-0000-0000-000000000004', 'Safeguarding concerns require action proportionate to risk, not to the apparent clinical severity of the presenting injury.', 3),
('e1000000-0000-0000-0000-000000000005', 'Core early red flags for autism spectrum disorder include reduced joint attention (not pointing/showing), poor eye contact, absent or delayed language, and repetitive/rigid behaviours or play.', 1),
('e1000000-0000-0000-0000-000000000005', 'A normal hearing screen or normal motor milestones do not exclude autism spectrum disorder, which is a disorder of social communication rather than of hearing or motor function.', 2),
('e1000000-0000-0000-0000-000000000005', $x$Any suspicion of autism spectrum disorder warrants referral for a structured multidisciplinary developmental assessment rather than reassurance or a 'wait and see' approach.$x$, 3),
('e1000000-0000-0000-0000-000000000006', 'The triad of subdural haematoma, retinal haemorrhages, and encephalopathy without a clear history of significant trauma is strongly suggestive of abusive head trauma in infants.', 1),
('e1000000-0000-0000-0000-000000000006', 'Absence of external bruising does not exclude abusive head trauma; the responsible forces (shaking, impact) can cause severe internal injury without visible skin marks.', 2),
('e1000000-0000-0000-0000-000000000006', 'Vitamin K deficiency bleeding and coagulopathies should be actively excluded as part of the work-up, but their consideration must run alongside, not delay, urgent safeguarding referral and multidisciplinary child protection assessment.', 3),
('e1000000-0000-0000-0000-000000000007', 'Faltering growth is typically defined by a fall of one or more centile spaces if birthweight was below the 9th centile, two spaces if between the 9th-91st, or three spaces if above the 91st centile.', 1),
('e1000000-0000-0000-0000-000000000007', 'Assessment should combine a detailed feeding/dietary and psychosocial history, thorough examination, and targeted investigations rather than assuming either a purely organic or purely non-organic cause at the outset.', 2),
('e1000000-0000-0000-0000-000000000007', 'Normal developmental progress does not exclude significant faltering growth, as growth and developmental trajectories can be discordant, especially early in an evolving problem.', 3),
('e1000000-0000-0000-0000-000000000008', 'Jaundice within the first 24 hours of life is always pathological and requires urgent measurement of bilirubin and investigation for a haemolytic cause.', 1),
('e1000000-0000-0000-0000-000000000008', 'ABO incompatibility (mother O, baby A or B) and rhesus incompatibility are the classic causes of immune haemolytic jaundice, confirmed by a positive direct antiglobulin (Coombs) test.', 2),
('e1000000-0000-0000-0000-000000000008', 'Management depends on the bilirubin level plotted against gestation- and age-specific treatment threshold charts, and may require phototherapy or, in severe cases, exchange transfusion.', 3),
('e1000000-0000-0000-0000-000000000009', 'Prolonged neonatal jaundice is defined as jaundice persisting beyond 14 days in a term infant (21 days in a preterm infant) and always requires measurement of conjugated (split) bilirubin.', 1),
('e1000000-0000-0000-0000-000000000009', 'Pale stools and dark urine alongside prolonged jaundice suggest a conjugated hyperbilirubinaemia and must prompt urgent referral to exclude biliary atresia, as timely Kasai surgery improves outcomes.', 2),
('e1000000-0000-0000-0000-000000000009', 'Breast milk jaundice is a common benign cause of prolonged unconjugated jaundice in a well, thriving breastfed infant, but is a diagnosis of exclusion once conjugated causes have been ruled out.', 3),
('e1000000-0000-0000-0000-000000000010', 'Maternal GBS colonisation without adequate intrapartum antibiotic prophylaxis is a major risk factor for early-onset neonatal sepsis and should lower the threshold for treating a symptomatic neonate.', 1),
('e1000000-0000-0000-0000-000000000010', 'Signs of neonatal sepsis can be subtle and non-specific (lethargy, poor feeding, temperature instability, respiratory distress) but progression can be extremely rapid, so empirical intravenous antibiotics (typically benzylpenicillin plus gentamicin) are started immediately on clinical suspicion, without waiting for culture results.', 2),
('e1000000-0000-0000-0000-000000000010', 'A full septic screen (blood culture, CRP, consideration of lumbar puncture) is performed alongside, not instead of, prompt empirical treatment.', 3),
('e1000000-0000-0000-0000-000000000011', 'Respiratory distress syndrome results from surfactant deficiency in the immature preterm lung and classically produces a diffuse ground-glass appearance with air bronchograms on chest X-ray.', 1),
('e1000000-0000-0000-0000-000000000011', 'Antenatal corticosteroids given to the mother before preterm delivery accelerate fetal lung maturation and reduce the risk and severity of respiratory distress syndrome; missing this (as here, due to rapid delivery) increases risk.', 2),
('e1000000-0000-0000-0000-000000000011', 'Management combines respiratory support (CPAP or mechanical ventilation as needed) with exogenous surfactant therapy administered via the airway.', 3),
('e1000000-0000-0000-0000-000000000012', 'Infants of mothers with diabetes are at high risk of neonatal hypoglycaemia due to fetal hyperinsulinaemia in response to maternal hyperglycaemia in utero, and should have routine glucose monitoring after birth.', 1),
('e1000000-0000-0000-0000-000000000012', 'Symptomatic hypoglycaemia (jitteriness, lethargy, poor feeding, hypotonia) is an indication for prompt treatment, escalating from feeding to intravenous dextrose if glucose remains low or symptoms persist.', 2),
('e1000000-0000-0000-0000-000000000012', 'Untreated significant neonatal hypoglycaemia carries a risk of seizures and long-term neurodevelopmental harm, so it should never be observed passively in a symptomatic high-risk infant.', 3),
('e1000000-0000-0000-0000-000000000013', 'Necrotising enterocolitis classically presents in preterm infants with abdominal distension, bilious vomiting, bloody stools, and systemic instability (temperature instability, apnoea, lethargy).', 1),
('e1000000-0000-0000-0000-000000000013', 'Pneumatosis intestinalis (intramural gas) on abdominal X-ray is a characteristic radiological finding; free air indicates perforation and an absolute surgical emergency.', 2),
('e1000000-0000-0000-0000-000000000013', 'Initial management is medical (nil by mouth, nasogastric decompression, broad-spectrum antibiotics, supportive care) with early surgical involvement, escalating to laparotomy if there is perforation, worsening clinical status, or failure of medical management.', 3),
('e1000000-0000-0000-0000-000000000014', 'Hypoxic-ischaemic encephalopathy follows perinatal asphyxia and is suggested by severe acidosis, low Apgar scores needing prolonged resuscitation, and evolving encephalopathy (abnormal tone, consciousness, seizures).', 1),
('e1000000-0000-0000-0000-000000000014', 'Therapeutic hypothermia (cooling to a target core temperature, typically for 72 hours) started within 6 hours of birth improves survival and neurodevelopmental outcome in moderate-to-severe cases.', 2),
('e1000000-0000-0000-0000-000000000014', 'Affected infants need close neonatal intensive care monitoring for seizures, multi-organ dysfunction, and evolving severity, with cooling as the specific evidence-based neuroprotective intervention.', 3),
('e1000000-0000-0000-0000-000000000015', 'Small ventricular septal defects in asymptomatic, thriving infants are managed conservatively, as many close spontaneously; larger defects causing heart failure or failure to thrive need earlier surgical closure.', 1),
('e1000000-0000-0000-0000-000000000015', 'Signs prompting closer attention or earlier intervention include poor feeding, failure to thrive, tachypnoea, hepatomegaly, or echocardiographic evidence of pulmonary hypertension.', 2),
('e1000000-0000-0000-0000-000000000015', 'A murmur confirmed to represent a structural defect on echocardiogram still requires ongoing specialist follow-up, even when conservative management is appropriate.', 3),
('e1000000-0000-0000-0000-000000000016', $x$A hypercyanotic ('tet') spell in tetralogy of Fallot is triggered by crying, feeding, or agitation and causes worsening cyanosis with a softer murmur (due to reduced flow across the outflow tract obstruction).$x$, 1),
('e1000000-0000-0000-0000-000000000016', 'First-line management is calming the child, the knee-to-chest position, and high-flow oxygen, all aimed at increasing systemic vascular resistance and reducing right-to-left shunting.', 2),
('e1000000-0000-0000-0000-000000000016', 'Persistent spells escalate to morphine and beta-blockade, and severe/refractory spells are a medical emergency requiring senior paediatric and cardiology input.', 3),
('e1000000-0000-0000-0000-000000000017', 'Radiofemoral delay and a blood pressure differential between the upper and lower limbs are classic examination findings of coarctation of the aorta and should always be checked in a hypertensive child.', 1),
('e1000000-0000-0000-0000-000000000017', 'Coarctation of the aorta is a cause of secondary hypertension in children and can present at any age from neonatal collapse (duct-dependent) to incidental hypertension found later in childhood.', 2),
('e1000000-0000-0000-0000-000000000017', 'Diagnosis is confirmed by echocardiography, and management may involve balloon angioplasty/stenting or surgical repair depending on age and anatomy.', 3),
('e1000000-0000-0000-0000-000000000018', 'A haemodynamically significant PDA in a preterm infant presents with a continuous murmur, bounding pulses, widened pulse pressure, and increasing respiratory support needs, with echo showing significant shunting and cardiac dilatation.', 1),
('e1000000-0000-0000-0000-000000000018', 'First-line treatment for a significant symptomatic PDA in a preterm infant is a cyclo-oxygenase inhibitor (ibuprofen or indomethacin) to promote closure; surgical ligation is reserved for failed or contraindicated pharmacological treatment.', 2),
('e1000000-0000-0000-0000-000000000018', 'This is the opposite clinical scenario to duct-dependent congenital heart disease, where prostaglandin E1 is used to deliberately keep the ductus arteriosus open.', 3),
('e1000000-0000-0000-0000-000000000019', 'Neonatal collapse around day 2-5 of life, coinciding with physiological closure of the ductus arteriosus, should raise suspicion for duct-dependent congenital heart disease.', 1),
('e1000000-0000-0000-0000-000000000019', 'A hyperoxia test showing minimal improvement in saturations with 100% oxygen supports a cardiac rather than purely respiratory cause of cyanosis.', 2),
('e1000000-0000-0000-0000-000000000019', 'Prostaglandin E1 infusion to maintain ductal patency is a life-saving bridge therapy while urgent echocardiography and specialist cardiac transfer are arranged.', 3),
('e1000000-0000-0000-0000-000000000020', 'Innocent murmurs are typically soft, short, systolic, without radiation, vary with position or respiration, and occur in an otherwise asymptomatic child with normal examination and pulses.', 1),
('e1000000-0000-0000-0000-000000000020', 'Red flag features suggesting a pathological murmur include a loud murmur (grade 3 or above), a diastolic component, a thrill, radiation, fixed splitting of the second heart sound, or associated symptoms (poor feeding, failure to thrive, cyanosis).', 2),
('e1000000-0000-0000-0000-000000000020', 'No investigation is needed for a murmur with all the classic innocent features; referral for echocardiography is reserved for murmurs with concerning features or associated symptoms.', 3),
('e1000000-0000-0000-0000-000000000021', 'Kawasaki disease is diagnosed with fever for 5 or more days plus at least 4 of: bilateral conjunctival injection, oral/lip changes, polymorphous rash, extremity changes, and cervical lymphadenopathy.', 1),
('e1000000-0000-0000-0000-000000000021', 'Prompt treatment with intravenous immunoglobulin and high-dose aspirin, ideally within 10 days of fever onset, significantly reduces the risk of coronary artery aneurysms, the most serious complication.', 2),
('e1000000-0000-0000-0000-000000000021', 'Echocardiography is required at diagnosis and on follow-up to monitor for coronary artery involvement, which drives long-term surveillance and management.', 3),
('e1000000-0000-0000-0000-000000000022', 'Simple febrile seizures are generalised, last under 15 minutes, occur once in 24 hours, and are followed by full recovery, typically in children aged 6 months to 6 years.', 1),
('e1000000-0000-0000-0000-000000000022', 'Complex febrile seizures (focal, prolonged over 15 minutes, or recurring within 24 hours) or seizures with incomplete recovery/reduced consciousness warrant further investigation, including consideration of lumbar puncture or neuroimaging.', 2),
('e1000000-0000-0000-0000-000000000022', 'Management of simple febrile seizures centres on treating the underlying febrile illness, parental reassurance about generally good prognosis, and safety-netting advice rather than anticonvulsant prophylaxis or extensive investigation.', 3),
('e1000000-0000-0000-0000-000000000023', 'A non-blanching (purpuric or petechial) rash with fever in a child is a medical emergency and should be treated as meningococcal septicaemia until proven otherwise.', 1),
('e1000000-0000-0000-0000-000000000023', 'Empirical antibiotics (e.g. IV/IM benzylpenicillin in primary care, or IV ceftriaxone/cefotaxime in hospital) must be given immediately, without waiting for confirmatory investigations, alongside urgent fluid resuscitation for shock.', 2),
('e1000000-0000-0000-0000-000000000023', 'Lumbar puncture is contraindicated in the presence of shock, coagulopathy, signs of raised intracranial pressure, or a rapidly evolving rash, and must never delay treatment.', 3),
('e1000000-0000-0000-0000-000000000024', 'Anaphylaxis is recognised by acute onset of airway/breathing/circulation compromise (or skin/mucosal changes) after allergen exposure and requires immediate intramuscular adrenaline as first-line treatment.', 1),
('e1000000-0000-0000-0000-000000000024', 'Adrenaline should never be delayed while waiting for other treatments (antihistamines, steroids, bronchodilators); these are adjuncts, not substitutes.', 2),
('e1000000-0000-0000-0000-000000000024', 'Positioning should support circulation (lying flat with legs raised) unless respiratory distress predominates (sitting up); sudden standing risks cardiovascular collapse in a hypotensive patient.', 3),
('e1000000-0000-0000-0000-000000000025', 'Epiglottitis presents with rapid-onset high fever, toxic/anxious appearance, drooling (odynophagia/dysphagia), and stridor WITHOUT a barking cough, whereas croup has a more gradual onset with a hoarse, barking cough.', 1),
('e1000000-0000-0000-0000-000000000025', 'Any child with suspected epiglottitis should not have their throat examined or be distressed unnecessarily, as this can precipitate complete airway obstruction; senior anaesthetic and ENT input should be sought urgently for controlled airway management.', 2),
('e1000000-0000-0000-0000-000000000025', 'Reduced incidence of epiglottitis is attributed to Haemophilus influenzae type b (Hib) vaccination, but it still occurs and must be recognised promptly given its life-threatening potential.', 3),
('e1000000-0000-0000-0000-000000000026', 'Paediatric DKA management requires cautious, carefully calculated fluid resuscitation because of the specific risk of cerebral oedema, which is a leading cause of DKA-related mortality in children.', 1),
('e1000000-0000-0000-0000-000000000026', 'A fixed-rate intravenous insulin infusion is used (rather than adjusting the rate up and down) alongside fluids and potassium replacement, with frequent monitoring of glucose, ketones, electrolytes, and neurological status.', 2),
('e1000000-0000-0000-0000-000000000026', 'Routine sodium bicarbonate is avoided in paediatric DKA, as it offers no proven benefit and may increase the risk of cerebral oedema.', 3),
('e1000000-0000-0000-0000-000000000027', 'In choking, the key distinction is between an effective cough (can cry/vocalise, forceful cough, maintains colour) and an ineffective cough (silent or weak cough, cyanosis, decreasing consciousness); management differs accordingly.', 1),
('e1000000-0000-0000-0000-000000000027', 'With an effective cough, encourage continued coughing and observe closely; only escalate to back blows and chest thrusts (in infants) or back blows and abdominal thrusts (in children over 1 year) if the cough becomes ineffective.', 2),
('e1000000-0000-0000-0000-000000000027', 'Blind finger sweeps are avoided as they risk pushing the object deeper or causing airway trauma; visible objects may be removed carefully under direct vision only.', 3),
('e1000000-0000-0000-0000-000000000028', 'Status epilepticus is defined as a seizure lasting 5 minutes or more, or recurrent seizures without recovery of consciousness in between, and requires stepwise escalating treatment.', 1),
('e1000000-0000-0000-0000-000000000028', 'The paediatric status epilepticus algorithm typically proceeds: first benzodiazepine dose (buccal midazolam/rectal diazepam/IV lorazepam) at 5 minutes, a second benzodiazepine dose (IV lorazepam if not already given) at 10 minutes if still seizing, then a second-line anticonvulsant (e.g. phenytoin, levetiracetam) if seizures persist beyond that.', 2),
('e1000000-0000-0000-0000-000000000028', 'Once intravenous access is secured, intravenous benzodiazepine (lorazepam) is preferred as the next step, rather than repeating a non-intravenous route.', 3),
('e1000000-0000-0000-0000-000000000029', $x$Pyloric stenosis classically presents at 4-6 weeks of age with non-bilious projectile vomiting, a hungry infant after vomiting, and a palpable 'olive' mass, most commonly in a first-born male.$x$, 1),
('e1000000-0000-0000-0000-000000000029', 'Persistent vomiting of gastric contents causes a hypochloraemic, hypokalaemic metabolic alkalosis, which must be corrected with intravenous fluids before any surgical intervention.', 2),
('e1000000-0000-0000-0000-000000000029', 'Abdominal ultrasound is the investigation of choice to confirm the diagnosis; pyloromyotomy is curative but is performed only once the infant is adequately resuscitated and biochemically stable.', 3),
('e1000000-0000-0000-0000-000000000030', 'Intussusception classically presents in infants aged 6 months to 2 years with intermittent colicky pain (drawing up legs, screaming), lethargy between episodes, redcurrant jelly stool, and a palpable sausage-shaped abdominal mass.', 1),
('e1000000-0000-0000-0000-000000000030', $x$Abdominal ultrasound is the first-line investigation, showing a characteristic 'target'/'doughnut' sign, and guides subsequent management.$x$, 2),
('e1000000-0000-0000-0000-000000000030', 'First-line treatment for a stable child without signs of perforation or peritonitis is reduction by air or contrast enema; surgery is reserved for failed reduction, perforation, or peritonism.', 3),
('e1000000-0000-0000-0000-000000000031', 'Coeliac disease should be suspected in a child with faltering growth, chronic diarrhoea, bloating, or unexplained anaemia, particularly after gluten-containing foods have been introduced to the diet.', 1),
('e1000000-0000-0000-0000-000000000031', 'Anti-TTG IgA is the first-line serological test, but total IgA should be checked alongside it, as IgA deficiency can cause a false-negative anti-TTG result.', 2),
('e1000000-0000-0000-0000-000000000031', 'Diagnosis is typically confirmed by duodenal biopsy (showing villous atrophy and crypt hyperplasia) performed while the child continues a normal gluten-containing diet, as a gluten-free diet started before biopsy can obscure the histological findings.', 3),
('e1000000-0000-0000-0000-000000000032', $x$Cow's milk protein allergy can present with a mix of gastrointestinal (vomiting, blood/mucus in stool, colic), cutaneous (eczema, urticaria), and occasionally respiratory symptoms in young infants.$x$, 1),
('e1000000-0000-0000-0000-000000000032', 'First-line management in formula-fed infants with suspected allergy is a trial of extensively hydrolysed formula; amino acid-based formula is reserved for severe cases or those not responding to hydrolysed formula.', 2),
('e1000000-0000-0000-0000-000000000032', $x$Standard soy formula is generally avoided as first-line due to cross-reactivity risk with cow's milk protein in infants with confirmed or suspected allergy.$x$, 3),
('e1000000-0000-0000-0000-000000000033', 'Bilious (green) vomiting in a neonate or young infant is a red flag symptom that must always be treated as malrotation with volvulus until proven otherwise.', 1),
('e1000000-0000-0000-0000-000000000033', 'Malrotation with volvulus is a surgical emergency because twisting of the midgut around the superior mesenteric artery can rapidly cause bowel ischaemia and necrosis.', 2),
('e1000000-0000-0000-0000-000000000033', 'Management combines urgent resuscitation and nasogastric decompression with emergency surgical referral; imaging (upper GI contrast study) should not delay definitive surgical assessment in a clearly unwell infant.', 3),
('e1000000-0000-0000-0000-000000000034', $x$Simple gastro-oesophageal reflux ('posseting', the 'happy spitter') is extremely common in infancy, typically improves with conservative measures, and usually resolves by around 12 months.$x$, 1),
('e1000000-0000-0000-0000-000000000034', 'Red flag features that should prompt further investigation include bilious or projectile vomiting, haematemesis, faltering growth, feeding refusal/distress, or respiratory symptoms, none of which are present here.', 2),
('e1000000-0000-0000-0000-000000000034', 'First-line management of simple reflux is reassurance combined with practical feeding advice (smaller, more frequent feeds; upright positioning), reserving pharmacological treatment for more troublesome or complicated cases.', 3),
('e1000000-0000-0000-0000-000000000035', 'Toddler diarrhoea is a common, benign cause of chronic loose stools (often containing undigested food) in an otherwise well, thriving child aged roughly 1-5 years, with normal growth being the key reassuring feature.', 1),
('e1000000-0000-0000-0000-000000000035', 'Alarm features that should prompt further investigation for an organic cause include faltering growth, blood/mucus in stool, nocturnal symptoms, or systemic illness -- none of which are present here.', 2),
('e1000000-0000-0000-0000-000000000035', 'Management is reassurance and simple dietary advice (ensuring adequate dietary fat, limiting excessive fruit juice and sugary drinks); the condition typically resolves spontaneously by school age.', 3),
('e1000000-0000-0000-0000-000000000036', 'The NICE traffic light system stratifies febrile children under 5 years into green (low risk), amber (intermediate risk), and red (high risk) based on colour, activity, respiratory, circulation/hydration, and other clinical features.', 1),
('e1000000-0000-0000-0000-000000000036', 'A child with all green features and no amber/red features can generally be managed with advice and safety-netting in the community, provided a benign cause of fever is identified or suspected.', 2),
('e1000000-0000-0000-0000-000000000036', 'The presence of even one red feature (e.g. reduced consciousness, non-blanching rash, significant respiratory distress) warrants urgent assessment/referral, regardless of how well the child otherwise appears.', 3),
('e1000000-0000-0000-0000-000000000037', 'Urinary tract infection is an important cause of fever without an obvious source in infants and young children and should always be actively considered and tested for with a urine sample.', 1),
('e1000000-0000-0000-0000-000000000037', 'A positive dipstick for leucocytes and/or nitrites supports a clinical diagnosis of UTI, but urine culture is needed to confirm the diagnosis and organism; empirical antibiotics are started promptly on clinical suspicion rather than delayed for culture results.', 2),
('e1000000-0000-0000-0000-000000000037', $x$Depending on the child's age, response to treatment, and recurrence, further imaging (renal ultrasound, and sometimes further studies) may be arranged after the acute infection to look for underlying renal tract abnormalities.$x$, 3),
('e1000000-0000-0000-0000-000000000038', 'Bulging fontanelle, lethargy, high-pitched cry, poor feeding, and irritability in a febrile infant are red flags for bacterial meningitis and must be acted on urgently.', 1),
('e1000000-0000-0000-0000-000000000038', 'Empirical intravenous antibiotics should be started immediately on clinical suspicion of bacterial meningitis, without waiting for lumbar puncture or culture results.', 2),
('e1000000-0000-0000-0000-000000000038', 'CT head before lumbar puncture is only needed if there are specific contraindications (e.g. signs of raised intracranial pressure, focal neurological signs, reduced consciousness); its absence here means LP can proceed promptly alongside antibiotics.', 3),
('e1000000-0000-0000-0000-000000000039', 'Varicella (chickenpox) infection in pregnancy can cause maternal complications (e.g. varicella pneumonia) and, depending on gestational timing, congenital varicella syndrome or severe neonatal varicella.', 1),
('e1000000-0000-0000-0000-000000000039', 'The first step after significant exposure in a pregnant woman is to establish her immunity status (history of prior chickenpox, or varicella IgG testing if uncertain).', 2),
('e1000000-0000-0000-0000-000000000039', 'Non-immune pregnant women after significant exposure require specific post-exposure management (such as varicella-zoster immunoglobulin or antiviral treatment per current guidance), and the live varicella vaccine is contraindicated in pregnancy.', 3),
('e1000000-0000-0000-0000-000000000040', 'Scarlet fever is caused by an exotoxin-producing Group A streptococcus and classically presents with fever, sore throat, a sandpaper-textured rash sparing the area around the mouth, strawberry tongue, and cervical lymphadenopathy.', 1),
('e1000000-0000-0000-0000-000000000040', 'First-line treatment is a 10-day course of oral penicillin V, which reduces symptom duration, transmission, and the risk of complications including rheumatic fever and post-streptococcal glomerulonephritis.', 2),
('e1000000-0000-0000-0000-000000000040', 'Scarlet fever is a notifiable disease in the UK, requiring public health notification alongside treatment.', 3),
('e1000000-0000-0000-0000-000000000041', $x$Parvovirus B19 (erythema infectiosum/fifth disease) classically causes a 'slapped cheek' facial rash followed by a lacy, reticular rash on the limbs, with the preceding febrile phase being the infectious period rather than the rash phase itself.$x$, 1),
('e1000000-0000-0000-0000-000000000041', 'Parvovirus B19 infection in pregnancy carries a risk of fetal anaemia and hydrops fetalis, particularly with infection in the first half of pregnancy, and significant exposures in pregnant women should be assessed and discussed with obstetric services.', 2),
('e1000000-0000-0000-0000-000000000041', 'By the time the characteristic rash of parvovirus B19 appears, the child is typically no longer infectious, which is a useful and commonly tested point distinguishing it from other childhood exanthems.', 3),
('e1000000-0000-0000-0000-000000000042', 'Pertussis classically progresses through a catarrhal phase (resembling a viral URTI) followed by a paroxysmal phase with severe coughing bouts, an inspiratory whoop, and post-tussive vomiting.', 1),
('e1000000-0000-0000-0000-000000000042', 'Young infants may present atypically with apnoeic episodes rather than a classic whoop, and are at particular risk of severe complications including apnoea, pneumonia, and encephalopathy.', 2),
('e1000000-0000-0000-0000-000000000042', 'Pertussis is a notifiable disease; macrolide antibiotics are used for treatment (most effective if started early in the catarrhal phase) and prophylaxis may be offered to vulnerable close contacts.', 3),
('e1000000-0000-0000-0000-000000000043', 'Bronchiolitis, most commonly caused by RSV, typically affects infants under 12 months with a preceding coryzal illness progressing to cough, crackles, and often wheeze, with symptoms peaking around day 3-5.', 1),
('e1000000-0000-0000-0000-000000000043', 'Admission criteria include significant hypoxia, apnoeic episodes, marked respiratory distress, and reduced feeding (commonly below 50-75% of usual intake), or clinician concern about the trajectory of illness.', 2),
('e1000000-0000-0000-0000-000000000043', 'Management is supportive only (oxygen, fluid support as needed); antibiotics, bronchodilators, and corticosteroids have no proven benefit in typical bronchiolitis.', 3),
('e1000000-0000-0000-0000-000000000044', 'Viral-induced (episodic) wheeze occurs specifically during viral respiratory infections, with complete symptom resolution and normal respiratory function between episodes, and typically no interval or atopic symptoms.', 1),
('e1000000-0000-0000-0000-000000000044', 'Multiple-trigger wheeze/asthma is suggested by wheeze also occurring between infections (e.g. with exercise, allergens, cold air, or at night), and is more strongly associated with personal or family atopy.', 2),
('e1000000-0000-0000-0000-000000000044', 'Viral-induced wheeze in preschool children often improves and resolves as the child grows, reflecting relative airway narrowness at this age rather than a fixed diagnosis of asthma.', 3),
('e1000000-0000-0000-0000-000000000045', 'Acute asthma severity in children is assessed using ability to talk/feed, respiratory rate, oxygen saturation, peak flow (where measurable), and presence of life-threatening features (silent chest, cyanosis, exhaustion, poor respiratory effort).', 1),
('e1000000-0000-0000-0000-000000000045', 'First-line treatment for moderate-to-severe exacerbations is high-dose short-acting beta-2 agonist (via spacer or nebuliser) plus oral corticosteroids, with escalation (ipratropium bromide, IV magnesium/salbutamol/aminophylline, HDU/ICU input) guided by response and severity.', 2),
('e1000000-0000-0000-0000-000000000045', 'Life-threatening features (silent chest, cyanosis, exhaustion, poor respiratory effort, hypotension, confusion) mandate immediate senior/critical care escalation, which is not indicated in this moderate presentation.', 3),
('e1000000-0000-0000-0000-000000000046', 'Pneumonia in children can be diagnosed clinically from fever, tachypnoea, and focal chest signs (reduced air entry, bronchial breathing, crackles); chest X-ray is not routinely required for straightforward outpatient management.', 1),
('e1000000-0000-0000-0000-000000000046', 'First-line oral antibiotic treatment for community-acquired pneumonia in children is amoxicillin; macrolides are typically added or substituted for atypical cover, penicillin allergy, or non-response.', 2),
('e1000000-0000-0000-0000-000000000046', 'Admission and intravenous antibiotics are reserved for children who are more unwell (significant hypoxia, severe respiratory distress, unable to tolerate oral treatment, or signs of complications such as empyema).', 3),
('e1000000-0000-0000-0000-000000000047', 'Cystic fibrosis should be suspected in a child with recurrent chest infections combined with features of pancreatic exocrine insufficiency (steatorrhoea, faltering growth despite good appetite), particularly if newborn screening was missed.', 1),
('e1000000-0000-0000-0000-000000000047', 'The sweat chloride test remains the gold-standard diagnostic investigation for cystic fibrosis, supported by CFTR genetic mutation testing.', 2),
('e1000000-0000-0000-0000-000000000047', 'Cystic fibrosis is a multisystem disease requiring long-term multidisciplinary management, including airway clearance, treatment of infections, and pancreatic enzyme replacement therapy.', 3),
('e1000000-0000-0000-0000-000000000048', 'A sudden choking or coughing episode followed by persistent unilateral wheeze and reduced air entry on one side is a classic presentation of foreign body aspiration, especially in toddlers exploring objects orally.', 1),
('e1000000-0000-0000-0000-000000000048', 'The child may appear entirely well between coughing episodes, and normal oxygen saturation does not exclude a retained foreign body; clinical suspicion based on history and unilateral signs should drive urgent referral.', 2),
('e1000000-0000-0000-0000-000000000048', 'Rigid bronchoscopy under general anaesthesia is both diagnostic and therapeutic, and should not be delayed for other imaging or trial treatments once foreign body aspiration is clinically suspected.', 3),
('e1000000-0000-0000-0000-000000000049', 'Adenotonsillar hypertrophy is the most common cause of obstructive sleep apnoea in children, presenting with loud snoring, witnessed apnoeic pauses with gasping, restless sleep, and daytime symptoms such as irritability or poor concentration.', 1),
('e1000000-0000-0000-0000-000000000049', 'Examination findings such as large tonsils and adenoidal facies support the diagnosis, and referral to ENT (with consideration of sleep studies where needed) is the appropriate next step.', 2),
('e1000000-0000-0000-0000-000000000049', 'Adenotonsillectomy is generally curative for obstructive sleep apnoea caused by adenotonsillar hypertrophy in children, distinguishing management from that of adult obstructive sleep apnoea (often more related to obesity and managed with CPAP).', 3),
('e1000000-0000-0000-0000-000000000050', 'Croup classically causes a barking cough, hoarse voice, and inspiratory stridor, typically caused by parainfluenza virus, and usually affects children aged 6 months to 6 years.', 1),
('e1000000-0000-0000-0000-000000000050', 'A single dose of oral dexamethasone is recommended for croup of any severity to reduce symptom severity, duration, and the likelihood of needing further medical attention.', 2),
('e1000000-0000-0000-0000-000000000050', 'Direct throat examination should be avoided in a stridulous child until epiglottitis has been excluded clinically, given the risk of precipitating complete airway obstruction; nebulised adrenaline is reserved for more severe croup with significant distress at rest.', 3);
